/* ================= שכבה 20 — גוף ובריאות + חוק וזכויות ================= */
const EXP20=[
// גוף ובריאות
{c:"גוף ובריאות",q:"מהו לחץ דם ״תקין״ ומה משמעות שני המספרים?",h:"120 על 80.",a:"סביב 120/80. המספר העליון (סיסטולי) — הלחץ כשהלב מתכווץ; התחתון (דיאסטולי) — כשהלב נרפה בין פעימות.",m:"מעל 140/90 לאורך זמן נחשב יתר לחץ דם — ״הרוצח השקט״, כי אין לו תסמינים.",d:"למה זה חשוב לך בפועל: לחץ דם גבוה לא מרגישים — הוא שוחק כלי דם בשקט במשך שנים ואז מגיע כשבץ או התקף לב. מדידה ביתית פעם בכמה חודשים (בישיבה, אחרי 5 דקות מנוחה, בלי קפה לפני) היא מהבדיקות הזולות והמשתלמות שיש. אצל צעירים ספורטיבים המספרים יכולים להיות נמוכים (110/70) וזה מצוין."},
{c:"גוף ובריאות",q:"מהו כולסטרול ״טוב״ ו״רע״?",h:"HDL מול LDL.",a:"LDL (״רע״) מוביל כולסטרול לדפנות העורקים ותורם לחסימה; HDL (״טוב״) אוסף עודפים חזרה לכבד לפינוי.",m:"רמת LDL מושפעת מגנטיקה, שומן רווי ושומן טראנס; HDL עולה עם פעילות אירובית.",d:"המספר היחיד שהרופאים מסתכלים עליו ברצינות בגיל צעיר הוא LDL — ככל שהוא נמוך יותר, לאורך יותר שנים, כך פחות רובד מצטבר בעורקים. יש אנשים עם גנטיקה של כולסטרול גבוה (היפרכולסטרולמיה משפחתית) שאצלם דיאטה לא מספיקה. בדיקת דם פשוטה פעם בכמה שנים מגלה את זה, ותרופות (סטטינים) הן מהמוכחות ביותר ברפואה."},
{c:"גוף ובריאות",q:"מה ההבדל בין התקף לב לדום לב?",h:"אחד הוא בעיית צנרת, השני בעיית חשמל.",a:"התקף לב — חסימה של עורק כלילי שמרעיבה חלק משריר הלב (האדם בדרך כלל בהכרה, עם כאב בחזה). דום לב — הלב מפסיק לפעום בגלל הפרעה חשמלית; האדם מתמוטט ואינו נושם, ובלי החייאה ודפיברילטור מת תוך דקות.",m:"התקף לב יכול להוביל לדום לב, אבל הם לא אותו דבר.",d:"הידע שמציל חיים: אדם שהתמוטט, לא מגיב ולא נושם כרגיל (או ״נושם״ בגניחות) — זה דום לב. לא בודקים דופק, לא מחכים: מתקשרים 101, מתחילים עיסויים חזקים ומהירים (100–120 בדקה, עומק 5–6 ס״מ) במרכז החזה, ושולחים מישהו להביא דפיברילטור (יש בקניונים, בחדרי כושר, בתחנות רכבת). כל דקה בלי החייאה מורידה ~10% מהסיכוי לשרוד."},
{c:"גוף ובריאות",q:"מהם סימני האזהרה של שבץ מוחי, ומה עושים?",h:"FAST.",a:"פנים שמוטות מצד אחד, זרוע שנופלת, דיבור משובש — וזמן: מתקשרים מיד. הטיפול (המסת קריש או שליפתו) יעיל רק בשעות הראשונות.",m:"מנמוניקה באנגלית: Face, Arms, Speech, Time.",d:"מה שאנשים מפספסים: שבץ לא כואב. אין ״אאוץ׳״, ולכן אנשים אומרים ״נלך לישון ונראה בבוקר״ — וזה ההבדל בין שיקום מלא לנכות. גם אם התסמינים חלפו אחרי כמה דקות (״שבץ חולף״, TIA) — זה אזהרה חמורה ומגיעים למיון באותו יום. תרשום את שעת ההתחלה — הרופאים יצטרכו אותה."},
{c:"גוף ובריאות",q:"למה מים מלוחים לא מרווים צימאון, ואיך התייבשות הורגת?",h:"אוסמוזה.",a:"הכליות צריכות יותר מים כדי לפנות את המלח מאשר מה ששתית — נטו מאבדים נוזלים. בהתייבשות נפח הדם יורד, לחץ הדם נופל, האיברים לא מקבלים חמצן, וחום הגוף עולה כי אין הזעה.",m:"סימן פשוט: שתן כהה = לשתות. צבע לימונדה בהירה = בסדר.",d:"על פלטפורמה בים או בשמש: איבוד של 2% ממשקל הגוף בנוזלים כבר פוגע בריכוז ובביצועים, לפני שמרגישים צמא אמיתי. במאמץ בחום מאבדים גם מלחים — ולכן ״רק מים״ בכמויות ענק בלי מלח יכול לגרום להיפונתרמיה (נתרן נמוך), שמסוכנת בעצמה. משקה איזוטוני או אוכל מלוח עם מים — נכון יותר ממים בלבד באימון ארוך."},
{c:"גוף ובריאות",q:"מהו מכת חום, ובמה היא שונה מתשישות חום?",h:"אחת מהן היא מצב חירום.",a:"תשישות חום: הזעה מרובה, חולשה, סחרחורת — טופלת בצל, מים והורדת מאמץ. מכת חום: חום גוף מעל 40°, בלבול או איבוד הכרה, לעיתים הפסקת הזעה — מצב חירום מסכן חיים; מקררים באגרסיביות (מים, קרח, רוח) ומפנים.",m:"בצה״ל מכת חום היא מהגורמים המובילים למוות בפעילות מבצעית ואימונים.",d:"הסימן המבדיל החשוב ביותר: שינוי במצב ההכרה. אדם מבולבל, מדבר שטויות, מתנהג מוזר בחום — זה מכת חום עד שיוכח אחרת, גם אם הוא עדיין מזיע. הקירור חייב להתחיל במקום, לפני הפינוי — כל דקה מעל 40° פוגעת במוח ובכליות. השיטה הכי יעילה בשטח: להרטיב את כל הגוף ולנפנף/לאוורר (התאדות), או אמבט מי קרח אם יש."},
{c:"גוף ובריאות",q:"מה עושה הכבד, ולמה הוא ״מפעל״ הגוף?",h:"האיבר הפנימי הגדול ביותר, ומסוגל לצמוח מחדש.",a:"מסנן רעלים מהדם (כולל אלכוהול ותרופות), מייצר מרה לעיכול שומן, אוגר סוכר (גליקוגן) ומשחרר אותו כשצריך, ומייצר חלבוני דם וגורמי קרישה.",m:"אפשר לתרום חלק מהכבד — הוא מתחדש לגודל כמעט מלא תוך חודשים.",d:"למה אלכוהול ותרופות לא מתערבבים: שניהם מפורקים בכבד, ולעיתים באותם אנזימים. אקמול (פרצטמול) במינון גבוה עם אלכוהול הוא מהשילובים המסוכנים ביותר בפועל — נזק לכבד שלא מרגישים עד שמאוחר. מינון יומי מקסימלי של אקמול למבוגר: 4 גרם (8 כדורים של 500 מ״ג), ופחות מזה אם שותים."},
{c:"גוף ובריאות",q:"מה ההבדל בין אקמול (פרצטמול) לאדוויל/נורופן (איבופרופן)?",h:"אחד נוגד דלקת, השני לא.",a:"איבופרופן הוא נוגד דלקת (NSAID) — טוב לכאב עם דלקת/נפיחות (פציעה, כאבי שיניים, מחזור), אבל מגרה קיבה ומעמיס על הכליות. פרצטמול מוריד חום ומשכך כאב בלי לטפל בדלקת, עדין לקיבה, אבל רעיל לכבד במינון יתר.",m:"אפשר לשלב ביניהם (הם פועלים במנגנונים שונים) — כך עושים במיון.",d:"טיפים שרופאים נותנים: איבופרופן תמיד עם אוכל, לא על קיבה ריקה, ולא כשמיובשים (הכליות). מי שיש לו כיב, אסתמה או בעיות כליה — לא איבופרופן. אקמול — לספור את המינון היומי כולל תרופות ״שפעת״ משולבות שמכילות אותו בלי שמים לב."},
{c:"גוף ובריאות",q:"מהי הלם (שוק) במובן הרפואי?",h:"לא ההלם הרגשי.",a:"מצב שבו זרימת הדם לא מספיקה לספק חמצן לאיברים — מדימום, התייבשות, אלרגיה חמורה, זיהום או כשל לב. סימנים: דופק מהיר וחלש, עור חיוור וקר, בלבול, לחץ דם יורד.",m:"הלם הוא ״המסלול הסופי המשותף״ של רוב מקרי המוות מפציעה.",d:"בשטח: הגוף מפצה בהתחלה — מכווץ כלי דם בגפיים ומעלה דופק — ולכן לחץ הדם נשאר תקין עד שאבד כבר 30% מהדם. דופק מעל 100 עם עור קר וחיוור אחרי פציעה = הלם מתפתח, גם אם ״הוא מדבר בסדר״. הטיפול המשמעותי היחיד בשטח לדימום הוא לעצור אותו: לחץ ישיר, חוסם עורקים בגפה, ופינוי מהיר."},
{c:"גוף ובריאות",q:"למה אנחנו ישנים, ומה קורה במוח בזמן שינה?",h:"לא רק מנוחה — ניקיון ותיוק.",a:"בשינה המוח מקבע זיכרונות (מעביר מהיפוקמפוס לקליפת המוח), מפנה פסולת חלבונית דרך מערכת ״ניקוז״ (הגלימפטית), ומאזן הורמונים. חוסר שינה פוגע בקבלת החלטות, בחיסון ובוויסות רעב.",m:"אחרי 17–19 שעות ערות הביצועים דומים לנהיגה עם אלכוהול בדם ברמה של 0.05%.",d:"בשביל אפליקציה כמו זו: הזיכרון של מה שלמדת נסגר בזמן השינה. סבב לפני שינה ולמחרת בבוקר חזרה קצרה — זה השילוב שהמחקר תומך בו. במשמרות עם שעות מפוצלות: נמנום של 20 דקות משפר ערנות בלי ״ערפל״; נמנום של 90 דקות משלים מחזור שינה שלם. הבעיה היא ה־45 דקות באמצע — מתעוררים בשינה עמוקה ומרגישים גרוע."},
{c:"גוף ובריאות",q:"מהו BMI, ולמה הוא לא מספר לכל הסיפור?",h:"משקל חלקי גובה בריבוע.",a:"מדד מסת גוף: משקל (ק״ג) חלקי גובה (מטר) בריבוע. 18.5–25 ״תקין״, 25–30 עודף, מעל 30 השמנה. לא מבחין בין שריר לשומן — מתאמנים שריריים יוצאים ״בעודף משקל״.",m:"היקף מותניים ושומן בטני מנבאים סיכון בריאותי טוב יותר מ־BMI לבד.",d:"מה כן שווה למדוד: היקף מותניים (מעל 94 ס״מ לגברים מתחיל סיכון, מעל 102 סיכון גבוה), כי שומן בטני עמוק סביב האיברים הוא זה שקשור לסוכרת ולמחלות לב — לא השומן מתחת לעור. גבר עם BMI 27 ומותניים של 85 בריא יותר מגבר עם BMI 24 ומותניים של 100."},
{c:"גוף ובריאות",q:"מהי סוכרת סוג 2, ולמה היא ״מחלת אורח חיים״?",h:"הגוף מפסיק להקשיב לאינסולין.",a:"התאים נעשים עמידים לאינסולין, הסוכר נשאר בדם ופוגע בכלי דם, עיניים, כליות ועצבים. הגורמים העיקריים: שומן בטני, חוסר תנועה וגנטיקה. ניתנת למניעה ולעיתים להיפוך בשלבים מוקדמים.",m:"״טרום־סוכרת״ — סוכר גבוה מהתקין אך לא סוכרת — ניתנת להיפוך מלא בשינוי אורח חיים.",d:"מה הכי עובד לפי המחקר: ירידה של 5–7% ממשקל הגוף ו־150 דקות הליכה בשבוע מורידות את הסיכון לעבור מטרום־סוכרת לסוכרת בכ־58% — יותר מהתרופה המקובלת (מטפורמין). שריר הוא ״ספוג סוכר״: אימון כוח משפר רגישות לאינסולין ל־24–48 שעות אחרי כל אימון."},
{c:"גוף ובריאות",q:"למה חיסונים עובדים?",h:"אימון למערכת החיסון עם ״אויב מדומה״.",a:"מציגים לגוף חלק לא מזיק מהמחולל (או גרסה מוחלשת/מומתת), הוא מייצר נוגדנים ותאי זיכרון, וכשנפגוש את הדבר האמיתי — התגובה מהירה וחזקה מספיק כדי למנוע מחלה.",m:"״חסינות עדר״: כשמספיק אנשים מחוסנים, המחלה לא מוצאת נתיב להתפשט ומגנה גם על מי שלא יכול להתחסן.",d:"הדוגמה ההיסטורית שכדאי לזכור: אבעבועות שחורות — מחלה שהרגה כ־300 מיליון איש במאה ה־20 לבדה — הוכרזה כמוגרת ב־1980, המחלה האנושית הראשונה והיחידה שנמחקה מהעולם, רק בזכות חיסונים. פוליו קרוב לזה. הפער בין ״אחרי החיסון היה לי חום״ (מערכת חיסון עובדת) ל״החיסון גרם למחלה״ הוא ההבדל שכדאי להסביר לאנשים."},
{c:"גוף ובריאות",q:"מהו אלרגיה, ומהו הלם אנפילקטי?",h:"מערכת חיסון שמגיבה בטירוף למשהו לא מזיק.",a:"אלרגיה — תגובה מוגזמת של מערכת החיסון לחומר לא מזיק (בוטנים, עקיצת דבורה, פניצילין). אנפילקסיס — תגובה מערכתית מסכנת חיים: נפיחות בגרון, קוצר נשימה, נפילת לחץ דם. הטיפול המיידי: אדרנלין (אפיפן) לירך.",m:"אנטיהיסטמין (טלפסט/פניסטיל) עוזר לפריחה וגרד — לא לאנפילקסיס.",d:"כללים לשטח: אפיפן נותנים דרך הבגדים, לירך החיצונית, מחזיקים 3 שניות. אם אין שיפור תוך 5–15 דקות — מנה שנייה. אחרי אפיפן חייבים למיון גם אם הכל נראה בסדר, כי יש ״גל שני״ אצל כ־20% מהמקרים, שעות אחר כך. אדם עם קוצר נשימה יושב — לא משכיבים אותו על הגב."},
{c:"גוף ובריאות",q:"מה קורה בגוף כשמעשנים סיגריה אחת?",h:"תוך 10 שניות.",a:"ניקוטין מגיע למוח תוך ~10 שניות ומשחרר דופמין (ההתמכרות); פחמן חד־חמצני נקשר להמוגלובין במקום חמצן; כלי הדם מתכווצים ולחץ הדם והדופק עולים; ריסי הריאה משותקים לשעות.",m:"עישון הוא הגורם הנמנע מספר אחת למוות בעולם המפותח — כ־8 מיליון מתים בשנה.",d:"מה שמפתיע אנשים: הנזק הלבבי מתחיל מסיגריה אחת ביום — הסיכון להתקף לב עם סיגריה אחת ביום הוא כמחצית מהסיכון של קופסה, לא אחד חלקי עשרים. ומהצד השני: 20 דקות אחרי הפסקה הדופק יורד, שנה אחרי — סיכון לב ירד בחצי, 10 שנים — סיכון לסרטן ריאה ירד בחצי. הגוף סולח, אבל בקצב שלו."},
{c:"גוף ובריאות",q:"מהו קפאין ואיך הוא מעיר?",h:"הוא לא נותן אנרגיה — הוא חוסם עייפות.",a:"קפאין נראה כמו אדנוזין — המולקולה שמצטברת במוח במשך היום ויוצרת עייפות — ונתקע לה בקולטנים. המוח לא ״שומע״ את העייפות, אבל האדנוזין ממשיך להצטבר.",m:"זמן מחצית חיים: 5–6 שעות. קפה בשש בערב = חצי מהקפאין עדיין במוח בחצות.",d:"שלוש עובדות שימושיות: 1) הקאפה של ״ריסוק אחר הצהריים״ אחרי קפה בבוקר היא האדנוזין שנשפך על הקולטנים כשהקפאין מתפנה. 2) בשמירה בלילה — קפאין עובד הכי טוב בקפיצות קטנות (100 מ״ג כל כמה שעות) ולא כמנה אחת ענקית. 3) קפאין 90 דקות אחרי ההתעוררות ולא מיד — כי קורטיזול הבוקר כבר מעיר לבד, והקפה נשמר לאחר כך."},
{c:"גוף ובריאות",q:"מהו חלבון ולמה הגוף צריך אותו?",h:"אבני הלגו של הגוף.",a:"חלבונים בנויים מחומצות אמינו ומרכיבים שרירים, עור, אנזימים, נוגדנים והורמונים. הגוף לא אוגר חלבון — צריך אספקה יומית. 9 חומצות אמינו ״חיוניות״ מגיעות רק מהמזון.",m:"המלצה למתאמנים: 1.6–2.2 גרם לק״ג משקל גוף ביום.",d:"למה ״חלבון מלא״ משנה: מוצרים מהחי (ביצה, בשר, חלב) מכילים את כל 9 החיוניות; רוב הצמחיים חסרים אחת או שתיים — לכן משלבים (אורז + קטניות = מלא). ולמה מפזרים על פני היום: הגוף מנצל לבניית שריר בערך 30–40 גרם בארוחה — 150 גרם בארוחה אחת לא ״נאגרים״, חלקם פשוט נשרף כאנרגיה."},
{c:"גוף ובריאות",q:"מה ההבדל בין נקע, מתיחה ושבר, ואיך מטפלים בשטח?",h:"RICE.",a:"נקע — פגיעה ברצועות של מפרק; מתיחה — פגיעה בשריר או גיד; שבר — בעצם. בשטח: מנוחה, קרח, חבישה לוחצת, הגבהה (RICE). חשד לשבר: קיבוע ואיסור דריכה.",m:"סימני שבר: עיוות, אי־יכולת להעמיס משקל, כאב נקודתי מדויק על העצם, קול ״קראק״.",d:"מבחן אצבע לקרסול (״כללי אוטווה״): אם אפשר לדרוך 4 צעדים מיד אחרי הפציעה וגם במיון, ואין רגישות בלחיצה על העצמות הבולטות של הקרסול — סיכוי גבוה שאין שבר. הקרח: 15–20 דקות, לא ישירות על העור, כל 2–3 שעות ב־48 השעות הראשונות. חום (אמבטיה חמה) ב־48 השעות הראשונות מגביר את הנפיחות."},
{c:"גוף ובריאות",q:"מה ההבדל בין הורמון לנוירוטרנסמיטר?",h:"דואר לעומת טלפון.",a:"הורמון — שליח כימי שמופרש לדם ומגיע לאיברים רחוקים, פועל לאט וארוך (אינסולין, טסטוסטרון, קורטיזול). נוירוטרנסמיטר — שליח בין תאי עצב צמודים, פועל תוך אלפיות שנייה (דופמין, סרוטונין).",m:"אדרנלין הוא שניהם — הורמון מבלוטת יותרת הכליה וגם נוירוטרנסמיטר במוח.",d:"למה זה עוזר להבין תרופות ואימון: קורטיזול (הורמון סטרס) גבוה כרונית = שומן בטני, שינה גרועה, חיסון מוחלש. אימון כוח מעלה טסטוסטרון והורמון גדילה לשעות. נוגדי דיכאון מסוג SSRI משאירים סרוטונין יותר זמן במרווח בין העצבים. ״דופמין״ הוא לא ״הנאה״ אלא ״רצון/מוטיבציה לרדוף״ — לכן טלפון בכל 30 שניות מרוקן את המוטיבציה לדברים ארוכים."},
// חוק וזכויות (ישראל)
{c:"חוק וזכויות",q:"מהו חוק ״שכירות הוגנת״, ומה הוא קובע לגבי פיקדון?",h:"2017, ומגבלה של שלושה.",a:"תיקון מ־2017 לחוק השכירות: המשכיר חייב למסור דירה ראויה למגורים (מים, חשמל, אוורור, בלי סכנה בטיחותית), לתקן ליקויים מהותיים תוך זמן סביר, וסכום הערבויות/פיקדון מוגבל לפי הנמוך מבין שכר דירה של 3 חודשים או שליש מדמי השכירות לכל התקופה.",m:"החוק חל על דירות עד 20,000 ₪ לחודש.",d:"מה כדאי לדעת לפני חתימה: 1) בלאי סביר (״שחיקה רגילה״) לא מקוזז מהפיקדון — רק נזק. 2) צלם את הדירה ביום הכניסה ושלח למשכיר במייל — זו הראיה שלך. 3) המשכיר יכול להיכנס לדירה רק בתיאום ובזמן סביר. 4) הסכם שלא בכתב תקף, אבל תמיד תדרוש כתוב. אמידר היא שוכר מיוחד עם כללים משלה, אבל העקרונות דומים."},
{c:"חוק וזכויות",q:"כמה ימי חופשה שנתית מגיעים לעובד בישראל בשנים הראשונות?",h:"בשנה החמישית זה כבר יותר.",a:"לפי חוק חופשה שנתית: בארבע השנים הראשונות — 16 ימים קלנדריים (=12 ימי עבודה בשבוע של 5 ימים), ועולה בהדרגה עד 28 ימים קלנדריים בשנה ה־14 ומעלה.",m:"ימי חופשה נצברים גם אם לא ניצלת — אבל המעסיק יכול להגביל צבירה.",d:"מה שרוב העובדים לא יודעים: בסיום עבודה משלמים לך פדיון על ימי חופשה שלא ניצלת — זה כסף. שווה לבדוק בתלוש ״יתרת חופשה״ פעם ברבעון. במשמרות של 14/14 החישוב מותאם למספר ימי העבודה בפועל — ההסכם הקיבוצי או האישי קובע."},
{c:"חוק וזכויות",q:"מהי הודעה מוקדמת לפיטורים/התפטרות, ומהו החישוב?",h:"עד חודש.",a:"עובד חודשי: בשנה הראשונה יום אחד לכל חודש עבודה (עד 6 חודשים), אחר כך 6 ימים + יומיים וחצי לכל חודש נוסף — ואחרי שנה: חודש שלם. חל על שני הצדדים — גם עובד שמתפטר.",m:"המעסיק יכול לוותר על העבודה בתקופת ההודעה — אבל חייב לשלם עליה.",d:"טעות נפוצה: עובד מתפטר ״מהיום״ — והמעסיק רשאי לקזז מהשכר האחרון את ימי ההודעה שלא ניתנו. מהצד השני, פיטורים בלי הודעה = פיצוי בגובה השכר של תקופת ההודעה. ובכל מקרה — הודעת פיטורים חייבת שימוע לפני: מכתב זימון, זמן סביר להתכונן, והזדמנות אמיתית להגיב. שימוע פגום = עילה לתביעה."},
{c:"חוק וזכויות",q:"מהי ״פנסיה חובה״, ומי מפריש כמה?",h:"מאז 2008.",a:"מ־2008 כל עובד שכיר זכאי להפרשה לפנסיה. השיעורים היום: העובד 6% מהשכר, המעסיק 6.5% תגמולים + 6% פיצויים (סה״כ 18.5%). ההפרשה מתחילה אחרי 6 חודשי עבודה (או מיד, אם יש לעובד קרן פעילה).",m:"רכיב הפיצויים מצטבר בקרן — בפיטורים משוחרר לעובד; בהתפטרות תלוי בהסכם (סעיף 14).",d:"״סעיף 14״ — הביטוי שכל עובד צריך להכיר: אם הוא בהסכם, המעסיק מפריש 8.33% לפיצויים והם שלך בכל מקרה, גם אם התפטרת — אבל המעסיק לא צריך להשלים ״פיצויים מוגדלים״ לפי השכר האחרון. בלי סעיף 14 — בהתפטרות רגילה לרוב לא מקבלים פיצויים בכלל. תבדוק בהסכם העבודה שלך אם מופיע ״סעיף 14 לחוק פיצויי פיטורים״."},
{c:"חוק וזכויות",q:"מהי קרן השתלמות, ולמה היא נחשבת ההטבה הכי שווה בתלוש?",h:"פטור ממס אחרי שש שנים.",a:"חיסכון לטווח בינוני: המעסיק מפריש עד 7.5% והעובד 2.5% מהשכר (עד תקרה). אחרי 6 שנים הכסף נזיל ופטור לגמרי ממס רווחי הון — האפיק היחיד בישראל עם פטור כזה.",m:"אפשר לא למשוך ולהמשיך לצבור — הפטור נשאר.",d:"החישוב שמשכנע: 10% מהשכר נכנסים כל חודש, מהם 7.5% שהמעסיק נותן — כלומר על כל שקל ששמת קיבלת שלושה. ואז הכל נצבר בשוק ההון בלי 25% מס על הרווחים. מי שמשאיר את הקרן ״מהשוקנת״ ולא מושך אחרי 6 שנים, ממשיך ליהנות מפטור על עוד עשורים של תשואה. אם מעסיק לא מציע — שווה לנהל על זה משא ומתן במקום על שכר ברוטו."},
{c:"חוק וזכויות",q:"מה עושה המוסד לביטוח לאומי, ומה מקבלים תמורת דמי הביטוח?",h:"הכל מהלידה ועד הזקנה.",a:"ביטוח סוציאלי ממלכתי: דמי אבטלה, דמי לידה, נכות כללית ומעבודה, קצבת זקנה, שאירים, ילדים, מילואים ופגיעה בעבודה. שכיר משלם אחוז מהשכר וגם המעסיק — כולל דמי ביטוח בריאות.",m:"עצמאי חייב לשלם בעצמו — ומי שלא, לא מבוטח לפגיעה בעבודה.",d:"הזכות שמעסיקים ״שוכחים״: תגמולי מילואים. ביטוח לאומי משלם למעסיק על ימי המילואים שלך והוא חייב להעביר לך את השכר המלא; ואם מקבלים ישירות — הסכום הוא לפי ממוצע 3 חודשי השכר האחרונים, מינימום יומי קבוע גם למי שהרוויח פחות. תביעה מגישים באתר, וגם ימי מילואים בודדים בשנה מזכים בתשלום מינימלי."},
{c:"חוק וזכויות",q:"מה קובע חוק הגנת הצרכן על ביטול עסקה שנעשתה באינטרנט או בטלפון?",h:"14 יום.",a:"עסקה ״מרחוק״ (אינטרנט/טלפון) ניתנת לביטול תוך 14 יום מקבלת המוצר (או מהעסקה בשירות), בלי לנמק. העסק רשאי לגבות דמי ביטול של עד 5% או 100 ₪ — הנמוך מביניהם.",m:"חריגים: מוצרים פסידים (מזון), מוצרים שיוצרו במיוחד עבורך, ומידע/תוכנה שנפתחו.",d:"גם בחנות פיזית: מוצר ״רגיל״ (בגדים, מכשירי חשמל) אפשר להחזיר תוך 14 יום אם לא נעשה בו שימוש והאריזה שלמה, וגם על זה יכולים לגבות עד 5%/100 ₪. עסקאות ״מתמשכות״ (חדר כושר, סלולר, טלוויזיה) — אפשר לבטל בכל עת בהודעה, והחיוב נפסק תוך 3 ימי עסקים. עסק שמתחמק — תלונה למועצה לצרכנות או לרשות להגנת הצרכן."},
{c:"חוק וזכויות",q:"מה ההבדל בין הסכם ממון לחזקת השיתוף, ולמה זה רלוונטי גם לזוגות לא נשואים?",h:"בית המשפט לא שואל אם התחתנתם.",a:"חזקת השיתוף: זוג שחי כ״ידועים בציבור״ שנים ומנהל חיים משותפים — בית המשפט עשוי לראות ברכוש שנצבר רכוש משותף, גם בלי נישואין. הסכם ממון (״הסכם חיים משותפים״) קובע מראש מה שייך למי, ומחייב אישור בבית משפט או נוטריון כשהוא בין בני זוג נשואים.",m:"רכוש מלפני הקשר (דירה, ירושה) בדרך כלל לא משותף — אבל השבחה שלו במהלך הקשר עשויה להיות.",d:"למה זה עניין של ניהול סיכונים ולא של אמון: אחרי 6 שנים ביחד עם משק בית משותף, אתם כבר ״ידועים בציבור״ לכל דבר. אם אחד מכם יקנה נכס ושמו לבד בטאבו, כסף משותף ששולם בו יכול להפוך אותו למשותף. הסכם קצר אצל עורך דין (כמה אלפי שקלים) מונע התדיינות של שנים. זה גם מסמך שקובע ירושה במקרה מוות בלי צוואה — ידוע בציבור יורש רק אם מוכיח את הקשר."},
{c:"חוק וזכויות",q:"מהי צוואה, ומה קורה למי שמת בלי צוואה בישראל?",h:"חוק הירושה מחליט במקומך.",a:"בלי צוואה — חוק הירושה (1965): בן/בת זוג מקבל/ת חצי (ובמקרים מסוימים גם המכונית וחפצי הבית), הילדים חולקים את החצי השני. אין ילדים — בן הזוג עם ההורים/אחים. צוואה גוברת על הכל, ויש 4 צורות תקפות: בכתב יד, בעדים, בפני רשות, ובעל־פה (״שכיב מרע״).",m:"צוואה בכתב יד תקפה רק אם כולה בכתב ידו של המצווה, עם תאריך וחתימה.",d:"נקודה שאנשים לא יודעים: כספי פנסיה וביטוח חיים לא עוברים לפי הצוואה אלא לפי ״מוטבים״ שרשומים בקרן — ואם לא עדכנת, ההורים (ברירת המחדל מגיל צעיר) יקבלו את הכל ולא בת הזוג. עדכון מוטבים בקרן הפנסיה ובקרן ההשתלמות לוקח 10 דקות באתר, ואף עורך דין לא יעזור לבת הזוג אחר כך אם לא עשית את זה."},
{c:"חוק וזכויות",q:"מהו ״שומר״ מבחינה משפטית, ומהם סמכויותיו של מאבטח לעומת שוטר?",h:"מאבטח אינו שוטר.",a:"מאבטח פועל מכוח חוק סמכויות לשם שמירה על ביטחון הציבור (2005): רשאי לדרוש הזדהות, לבצע חיפוש בכלים/גוף (בהסכמה, או בלי הסכמה בכניסה למקום מוגן), ולעכב חשוד עד הגעת שוטר. אין לו סמכות מעצר, חקירה או שימוש בכוח מעבר להגנה עצמית ולעיכוב סביר.",m:"סירוב לחיפוש בכניסה למקום מוגן = זכות המאבטח למנוע כניסה — לא לעצור.",d:"מה שמגן על מאבטח משפטית: פעולה במסגרת ההסמכה בלבד, תיעוד (יומן, דיווח מיידי), וכוח מידתי — הפעלת כוח מעבר לנדרש היא תקיפה גם כשהיא נגד עבריין. ״עיכוב״ אזרחי (סעיף 75 לחוק המעצרים) קיים לכל אדם שראה עבירת פשע מתבצעת — אבל מוגבל לזמן סביר עד הגעת שוטר, מקסימום 3 שעות."},
{c:"חוק וזכויות",q:"מה חובת הזדהות בפני שוטר, ומה מותר לשוטר לדרוש ממך ברחוב?",h:"תעודת זהות — כן. טלפון — לא בלי צו.",a:"חובה להזדהות בפני שוטר במדים או שהזדהה (שם + מספר אישי). שוטר רשאי לעכב עד 3 שעות אם יש חשד סביר לעבירה, ולערוך חיפוש בגוף/ברכב רק בחשד סביר לנשק/סם או בהסכמה. פתיחת טלפון או מסירת סיסמה — רק בהסכמה או בצו שופט.",m:"יש לך זכות לשתוק בחקירה (למעט זהות) וזכות להיוועץ בעורך דין לפני חקירה.",d:"הכלל המעשי: להזדהות בנימוס, לשאול ״האם אני מעוכב או חופשי ללכת?״ — שאלה שמחייבת תשובה, ולא להסכים ״בשקט״ לחיפוש: אם מסכימים, החיפוש חוקי גם בלי חשד. ולציין את זה בקול: ״אני לא מסכים לחיפוש״. שוטר חייב להזדהות אם ביקשת, ואת המספר האישי אפשר לרשום. צילום שוטר במרחב ציבורי מותר כל עוד לא מפריעים."},
{c:"חוק וזכויות",q:"מהו ״ביטוח חובה״ לרכב לעומת צד ג׳ ומקיף?",h:"רק אחד מהם הוא באמת חובה.",a:"חובה — מכסה נזקי גוף בלבד (לנהג, לנוסעים, להולכי רגל) — נהיגה בלעדיו היא עבירה פלילית. צד ג׳ — נזק לרכוש של אחרים שגרמת. מקיף — גם הרכב שלך (גניבה, תאונה, שריפה).",m:"ביטוח חובה משלם גם לנהג שאשם בתאונה — זו הסיבה שהוא חובה.",d:"נקודה שמשנה החלטות: על רכב ישן וזול (עד ~15–20 אלף ₪) המקיף לרוב לא משתלם — הפרמיה + ההשתתפות העצמית מתקרבות לשווי הרכב. צד ג׳ לעומת זאת תמיד שווה: תאונה עם מרצדס יכולה לעלות 100,000 ₪ מהכיס. ובחובה — ״שימושים״: אם ההצהרה היא ״נהג יחיד״ ומישהו אחר נהג, אין כיסוי."},
{c:"חוק וזכויות",q:"מהו ״לשון הרע״, ומה ההגנות העיקריות?",h:"אמת דיברתי.",a:"פרסום (גם בוואטסאפ קבוצתי) שעלול להשפיל אדם או לפגוע במשלח ידו. הגנות: ״אמת דיברתי״ ויש עניין ציבורי; ״הבעת דעה״ בתום לב על עובדות נכונות; ותקשורת מסוימת חסויה (בבית משפט, בכנסת).",m:"אפשר לתבוע פיצוי ללא הוכחת נזק עד 50,000 ₪ (כפול אם הפרסום בכוונה לפגוע).",d:"למה זה חשוב בעידן הרשתות: ביקורת על עסק בגוגל — לגיטימית כשהיא מתארת חוויה אמיתית (״חיכיתי 40 דקות״) ומסוכנת כשהיא קובעת עובדה שקרית (״הם גונבים״). שיתוף/לייק של פוסט משמיץ נחשב לפעמים כפרסום. והגנת ״אמת״ דורשת שתוכל להוכיח — לא שאתה מאמין."},
{c:"חוק וזכויות",q:"מהם ״זכויות יוצרים״, ומה מותר לעשות עם תוכן של אחרים?",h:"70 שנה אחרי המוות.",a:"הגנה אוטומטית על יצירה מקורית (טקסט, מוזיקה, קוד, צילום) מרגע יצירתה, ל־70 שנה אחרי מות היוצר. מותר ״שימוש הוגן״: ציטוט לביקורת, לימוד, דיווח חדשותי — במידה סבירה ועם ייחוס.",m:"רעיונות ועובדות לא מוגנים — רק הביטוי שלהם.",d:"דוגמה מהאפליקציה הזו: דמויות של ריק ומורטי מוגנות — לא רק השם, גם המראה. אבל ״הוויב״ — דיאלוג מהיר, הומור ניהיליסטי, פלטת צבעים — לא. אותו עיקרון בעסקים: אי אפשר להגן על רעיון לאפליקציה, רק על הקוד והעיצוב הספציפיים. תמונות מהאינטרנט לאתר עסקי = תביעות של אלפי שקלים לתמונה; תמונות ברישיון חופשי (Unsplash, ויקימדיה עם ייחוס) — הפתרון."},
{c:"חוק וזכויות",q:"מהו ״חוזה״ מבחינה משפטית — האם הודעת וואטסאפ מחייבת?",h:"הצעה + קיבול = חוזה.",a:"חוזה נכרת בהצעה וקיבול עם גמירות דעת ומסוימות — לא נדרש מסמך חתום. הודעה, מייל ואפילו הסכמה בעל־פה יכולים להיות חוזה מחייב. חריגים: עסקאות מקרקעין (חייבות כתב), צוואה, הסכם ממון.",m:"״זיכרון דברים״ על דירה הוא חוזה מחייב לכל דבר — לכן עורכי דין מזהירים ממנו.",d:"הכלל שמונע בעיות: כל סיכום מסחרי — לסכם במייל אחד עם ״כפי שסיכמנו: X, Y, Z״. זה מגן עליך לשני הכיוונים. במקרקעין (שכירות/קנייה) שום דבר בלי מסמך; ובעסקאות גדולות עם אנשים פרטיים (רכב, ציוד) — אפשר להוסיף ״ההסכם כפוף לחתימה על חוזה מפורט״ כדי לא ״להיתפס״ על הודעה."},
{c:"חוק וזכויות",q:"מהי ״תקופת ההתיישנות״ לתביעה אזרחית בישראל?",h:"שבע שנים ברוב המקרים.",a:"7 שנים לתביעה אזרחית רגילה (חוב, הפרת חוזה, נזק); 25 שנה בתביעות מקרקעין; נזקי גוף — 7 שנים מגילוי הנזק, עם תקרה. עבירות פליליות — לפי חומרתן (עוון 5 שנים, פשע 10, פשע חמור 20; רצח — ללא התיישנות).",m:"ההתיישנות היא הגנה שהנתבע צריך לטעון — בית המשפט לא מעלה אותה מעצמו.",d:"שימושי לעניינים יומיומיים: חוב לחברת סלולר או לעירייה שלא נתבע 7 שנים — התיישן (אם לא הודית בו בכתב או שילמת חלק, מה שמאפס את המונה). וחוב לביטוח לאומי — לא מתיישן כמו חוב רגיל, יש להם סמכויות גבייה מנהליות. ובשוק העבודה: תביעה על זכויות (שעות נוספות, פנסיה) — 7 שנים, אבל על הלנת שכר רק שנה."},
{c:"חוק וזכויות",q:"מהו חוק חופש המידע, ואיך משתמשים בו?",h:"1998 — לכל אזרח.",a:"כל אזרח או תושב זכאי לקבל מידע מרשות ציבורית (משרד ממשלתי, עירייה, חברה ממשלתית) בלי לנמק, תוך 30 יום (ניתן להארכה). חריגים: ביטחון, פרטיות, סודות מסחריים. אגרה סמלית.",m:"סירוב לא מנומק — ניתן לעתור לבית המשפט המחוזי.",d:"דוגמה מעשית: רוצים לדעת כמה תלונות הוגשו נגד קבלן, מה תוכנית הבנייה ליד הבית, או איזה תקציב הוקצה לפינוי־בינוי בשכונה שלך — בקשת חופש מידע ליחידה הממונה בעירייה או במשרד השיכון. גם מדיניות אמידר ופירוט זכויות דיירים ממשיכים נגישים בדרך הזו."},
{c:"חוק וזכויות",q:"מה ההבדל בין עבירה פלילית לעוולה אזרחית?",h:"מי תובע, ומה העונש.",a:"פלילי — המדינה תובעת, המטרה ענישה (מאסר, קנס), הרף להרשעה ״מעבר לספק סביר״. אזרחי — אדם תובע אדם, המטרה פיצוי, הרף ״מאזן הסתברויות״ (יותר מ־50%). אותו מעשה יכול להיות שניהם (תקיפה — כתב אישום וגם תביעת נזיקין).",m:"זיכוי בפלילי לא מונע חיוב באזרחי — הדוגמה המפורסמת: O.J. סימפסון.",d:"למה זה חשוב כשמישהו מזיק לך: תלונה במשטרה היא לא ״תביעה״ — המשטרה מחליטה אם לחקור, והפרקליטות אם להעמיד לדין, ואתה לא ״צד״. פיצוי בשבילך מגיע רק מתביעה אזרחית שאתה מגיש (עד 34,000 ₪ בבית משפט לתביעות קטנות, בלי עורך דין). שני המסלולים במקביל — לגיטימי ומקובל."},
];
Q.push(...EXP20);

/* ================= שכבה 20ב — איך דברים עובדים + פסיכולוגיה + כלכלה בפועל ================= */
const EXP20B=[
// איך דברים עובדים
{c:"איך דברים עובדים",q:"איך מקרר מקרר?",h:"הוא לא ״מייצר קור״ — הוא מזיז חום.",a:"גז קירור נדחס (מתחמם), משחרר חום דרך הסלילים מאחור, מתרחב בתוך המקרר (מתקרר בפתאומיות) וסופח חום מהאוכל — ושוב. מזגן עובד בדיוק אותו דבר.",m:"לכן מקרר פתוח מחמם את החדר: הוא מוציא יותר חום מאחור ממה שהוא סופח מלפנים.",d:"אותו עיקרון בדיוק — ״משאבת חום״ — הוא הסיבה שמזגן בחימום יעיל פי 3–4 מתנור חשמלי: תנור הופך חשמל לחום 1:1, מזגן משתמש בחשמל כדי *להזיז* חום מבחוץ פנימה, ומעביר 3–4 יחידות חום על כל יחידת חשמל. גם כשבחוץ 5 מעלות יש שם חום להעביר."},
{c:"איך דברים עובדים",q:"איך מטוס נשאר באוויר?",h:"הכנף דוחפת אוויר למטה.",a:"הכנף מעוצבת ומוטה כך שהיא מסיטה זרם אוויר כלפי מטה; לפי החוק השלישי של ניוטון האוויר דוחף את הכנף למעלה (עילוי). הפרש הלחצים מעל ומתחת לכנף הוא חלק מאותה תמונה. המנועים רק דוחפים קדימה — המהירות היא שיוצרת עילוי.",m:"בלי מנועים מטוס נוסעים מדאה כ־15 ק״מ קדימה על כל ק״מ גובה.",d:"למה זה מרגיע לדעת: ״מערבולות״ (טורבולנציה) הן שינויים בזרם האוויר — הכנף לא ״מאבדת״ עילוי, היא רק מקבלת אותו בפולסים, ומטוס נוסעים בנוי לעומסים פי כמה ממה שכל טורבולנציה מייצרת. ההמראה היא השלב הכי דורש כי המהירות נמוכה; ברגע שיש מהירות — יש עילוי, וגם כשל של מנוע אחד לא משנה את זה."},
{c:"איך דברים עובדים",q:"איך עובד מנוע בנזין, בארבע מילים?",h:"יניקה, דחיסה, פיצוץ, פליטה.",a:"הבוכנה יורדת ושואבת תערובת אוויר־דלק, עולה ודוחסת אותה, המצת מצית — הפיצוץ דוחף את הבוכנה למטה (זו העבודה), ואז היא עולה ופולטת את הגזים. ארבע פעימות, אלפי פעמים בדקה.",m:"סל״ד = סיבובי גל הארכובה לדקה. ב־3,000 סל״ד כל צילינדר ״מתפוצץ״ 25 פעם בשנייה.",d:"מנוע דיזל — אותו רעיון בלי מצת: דוחס את האוויר כל כך חזק (פי 15–20) שהוא מתחמם ל־500°+ והדלק מתלקח לבד כשמוזרק. לכן דיזל חזק במומנט (משאיות) וחסכוני, אבל רועש ומזהם בחלקיקים. ומנוע חשמלי? אין פעימות, אין הילוכים כמעט, מומנט מלא מאפס — 20 חלקים נעים במקום 2,000. לכן תחזוקה כמעט אפסית."},
{c:"איך דברים עובדים",q:"איך המים מגיעים לברז בקומה עשירית?",h:"לחץ, ולפעמים משאבה על הגג.",a:"רשת המים העירונית מסופקת בלחץ ממאגרים גבוהים או משאבות; זה מספיק ל־3–4 קומות. מעבר לזה — משאבה בבניין דוחפת למאגר על הגג, ומשם המים יורדים בכוח הכבידה לדירות.",m:"ההרגשה של ״לחץ חלש״ בקומות עליונות = אתה קרוב מדי לגג, אין מספיק גובה מעליך.",d:"מכאן גם ״מים חמים נגמרו״: דוד שמש הוא מיכל של 120–150 ליטר על הגג; קולטים מחממים אותו ביום, ובלילה או בחורף — גוף חימום חשמלי (2–3 קילוואט, ~1.5 ₪ לשעה). ההרגל של להשאיר את הדוד דלוק כל הזמן שורף חשמל על חימום מים שאף אחד לא משתמש בהם. שעון דוד/טיימר — החזר השקעה תוך חודשים."},
{c:"איך דברים עובדים",q:"איך הטלפון יודע איפה אתה גם בלי GPS?",h:"אנטנות, וויי־פיי, ובלוטות׳.",a:"משולש מאנטנות סלולריות (עוצמת האות מכמה אנטנות עם מיקום ידוע), מאגר ענק של רשתות Wi-Fi ומיקומן (גוגל/אפל מיפו את העולם דרך הטלפונים שלנו), ומשואות בלוטות׳ בתוך מבנים.",m:"GPS מדויק ל־3–5 מ׳ בשמיים פתוחים; Wi-Fi ל־20–30 מ׳; אנטנות ל־מאות מטרים.",d:"מה שכדאי לדעת על פרטיות: גם ״שירותי מיקום כבויים״ לא מונע מספק הסלולר לדעת בערך איפה אתה — האנטנה חייבת לדעת כדי לחבר שיחה. מה שכן בשליטתך: הרשאות לאפליקציות (״רק בזמן שימוש״), ו־Wi-Fi/בלוטות׳ שסורקים גם כשלא מחוברים. במקום עבודה רגיש — מצב טיסה זה הכיבוי היחיד האמיתי."},
{c:"איך דברים עובדים",q:"איך אינטרנט מגיע מארה״ב לישראל?",h:"לא דרך לוויינים.",a:"99% מהתעבורה הבין־יבשתית עוברת בכבלים תת־ימיים של סיבים אופטיים — אלפי ק״מ על קרקעית האוקיינוס, בעובי של צינור גינה. לישראל נכנסים כמה כבלים כאלה (בעיקר דרך הים התיכון לאירופה).",m:"אור עובר בסיב מניו־יורק לתל אביב תוך ~50 אלפיות שנייה — זה ה״פינג״.",d:"למה זה עניין ביטחוני אמיתי: מדינה עם 2–3 כבלים בלבד פגיעה — ניתוק שלהם (עוגן ספינה, חבלה) יכול לבודד אותה דיגיטלית. לכן ישראל פועלת להוסיף כבלים (כולל דרך ירדן וסעודיה למפרץ ולהודו, כחלק מהסכמי אברהם). כבלים תת־ימיים הם גם יעד ריגול: להתחבר אליהם בעומק הים זה מבצע שרק כמה מדינות יודעות לעשות."},
{c:"איך דברים עובדים",q:"איך כרטיס אשראי ״יודע״ לאשר עסקה תוך שנייה?",h:"ארבעה שחקנים בשנייה אחת.",a:"בית העסק → חברת הסליקה → רשת הכרטיס (ויזה/מאסטרקארד) → הבנק/חברת האשראי שהנפיקה לך — שבודקת מסגרת וחשד להונאה ומחזירה ״מאושר״. הכסף עצמו עובר רק ימים אחר כך.",m:"בישראל ״כרטיס אשראי״ הוא לרוב כרטיס חיוב נדחה — החיוב פעם בחודש; בעולם ״אשראי״ אמיתי הוא הלוואה מתגלגלת.",d:"מה שרוב האנשים בישראל לא יודעים שהם משלמים: העסק משלם עמלה של ~0.5–1.5% על כל עסקה — זה ״מחיר״ הכסף שלך, מגולם במחירים. הטבות (נקודות, קאשבק) ממומנות מזה. ו״תשלומים בלי ריבית״ — העסק משלם על זה לחברת האשראי; ״קרדיט״ — אתה משלם, ולרוב ריבית דו־ספרתית. תמיד לקרוא איזה מהשניים זה."},
{c:"איך דברים עובדים",q:"איך אמצעי תשלום כמו ביט או פייבוקס מעבירים כסף מיידית?",h:"הם לא מעבירים כסף מיידית.",a:"ההעברה בין המשתמשים מתבצעת בתוך המערכת של הבנק/החברה (״ספר חשבונות״ פנימי) ומקבלת אישור מיידי; ההתחשבנות האמיתית בין הבנקים מתבצעת ברקע, בסבב סליקה יומי.",m:"בישראל מ־2023 יש גם ״העברה מיידית״ בנקאית אמיתית (עד 30 שניות, 24/7).",d:"למה זה חשוב לביטחון שלך: מכיוון שהעברה בביט היא מיידית וסופית, הונאות ביט (״שלחתי בטעות, תחזיר״, ״קונה מיד 2 ששולח ״קישור לתשלום״״) הן מהנפוצות בישראל. כלל: ביט לא מבקש ממך *לשלם* כדי *לקבל* כסף; ואם ״נכנס לך כסף בטעות״ — לא מחזירים לפני שבודקים שהוא באמת נכנס (ולא הודעת SMS מזויפת)."},
{c:"איך דברים עובדים",q:"איך מנעול רגיל עובד, ואיך פורצים אותו?",h:"פינים בגובה הנכון.",a:"מנעול פינים: שורת פינים קפיציים בגבהים שונים חוסמת סיבוב של הגליל; המפתח הנכון מרים כל פין בדיוק לקו ההפרדה (״קו הגזירה״) ואז הגליל מסתובב. פריצה (פיקינג) מנצלת סיבולות ייצור — לוחצים קלות על הסיבוב ומרימים פין־פין.",m:"מנעולים ״מוגני פריצה״ מוסיפים פינים בצורות מיוחדות, גלילים כפולים, ומגנטים.",d:"מה שבאמת מגן על דלת: לא ה״כמה בריחים״ אלא הגליל (צילינדר) — צילינדר זול נפרץ ב״צביטה״ (שוברים אותו בכוח) תוך 30 שניות. צילינדר בתקן גבוה עם מגן שבירה + שרשרת/מוט פנימי — זה ההבדל. רוב הפריצות לדירות בישראל הן בכלל דרך חלון/מרפסת בקומות נמוכות או דלת לא נעולה, לא פיקינג מתוחכם."},
{c:"איך דברים עובדים",q:"איך מיקרוגל מחמם אוכל?",h:"הוא מרעיד מולקולות מים.",a:"גלי רדיו בתדר של 2.45 ג׳יגה־הרץ גורמים למולקולות מים (שהן קוטביות) להסתובב מיליארדי פעמים בשנייה — החיכוך הזה הוא חום. לכן מזון יבש מתחמם גרוע וכלים ריקים לא מתחממים.",m:"הרשת המתכתית בדלת: החורים קטנים מאורך הגל (12 ס״מ) — הגלים לא עוברים, האור כן.",d:"למה מיקרוגל לא ״מקרין״ את האוכל: גלי המיקרו אינם מייננים — אין להם מספיק אנרגיה לשבור קשרים כימיים או לפגוע ב־DNA, בניגוד לרנטגן. הם נעלמים ברגע שהמכשיר נכבה. הסכנה האמיתית: נקודות רתיחה ״מושהות״ במים שחוממו במיקרוגל — כוס מים חלקה יכולה להתפרץ כשמכניסים כפית. ומתכת: לא בגלל ״קרינה״ אלא בגלל קשתות חשמליות בקצוות חדים."},
{c:"איך דברים עובדים",q:"איך עובד מזומן: למה שטר של 200 ₪ שווה 200?",h:"אמון, וחוק.",a:"לשטר אין ערך פנימי — הוא ״הילך חוקי״: החוק מחייב לקבל אותו לפירעון חוב, והמדינה מקבלת אותו כמס. הערך נשמר כל עוד בנק ישראל מנהל את כמות הכסף כך שאמון הציבור נשמר.",m:"רק כ־10% מהכסף בישראל הוא מזומן פיזי; השאר — רישומים דיגיטליים בבנקים.",d:"מכאן ״הדפסת כסף״ ואינפלציה: אם הבנק המרכזי מגדיל את כמות הכסף מהר יותר מהכלכלה, לכל שקל יש פחות ״דברים״ לרדוף אחריהם והמחירים עולים. זה מה שקרה בקוביד — טריליוני דולרים נכנסו לשוק, והאינפלציה של 2022 הייתה תוצאה. וגם ההפך: בנק ישראל מעלה ריבית = מייקר את הכסף = פחות הלוואות = פחות כסף במחזור = מחירים נבלמים."},
{c:"איך דברים עובדים",q:"איך מסך טאץ׳ מרגיש את האצבע?",h:"חשמל, לא לחץ.",a:"מסך קיבולי: שכבה שקופה של אלקטרודות עם שדה חשמלי זעיר; האצבע (מוליכה, מלאה מים) ״גונבת״ מעט מטען בנקודת המגע, והבקר מחשב מהשינוי היכן נגעת. לכן כפפות רגילות ומסך רטוב לא עובדים.",m:"מסכי ״התנגדות״ ישנים (כספומטים) הרגישו לחץ — עבדו עם כל דבר, אבל בלי מולטי־טאץ׳.",d:"טיפ מעשי: מסך ״משתגע״ בגשם או עם אצבעות רטובות כי טיפות מים מוליכות ונרשמות כנגיעות. ייבוש עם בד = פתרון. וכפפות ״תואמות מסך״ — יש בהן חוט מוליך בקצות האצבעות שמעביר את הקיבול של היד."},
{c:"איך דברים עובדים",q:"איך עובדת הצפנה, ולמה ״קצה־לקצה״ בוואטסאפ משנה?",h:"מנעול שכל אחד יכול לסגור, אבל רק אחד לפתוח.",a:"הצפנה א־סימטרית: לכל אדם זוג מפתחות — ציבורי (כולם רואים, משמש לנעילה) ופרטי (רק אצלו, משמש לפתיחה). קצה־לקצה = ההודעה ננעלת במכשיר שלך עם המפתח הציבורי של הנמען ונפתחת רק במכשיר שלו; אפילו וואטסאפ לא יכולה לקרוא.",m:"אבל: גיבוי לענן, צילומי מסך, ומכשיר פרוץ — עוקפים הכל. ההצפנה מגנה על הדרך, לא על הקצוות.",d:"מה כן חשוף גם עם הצפנה: ״מטא־דאטה״ — מי דיבר עם מי, מתי, כמה זמן, מאיפה. זה מה שרשויות וגורמי ביון בעיקר רוצים, ולעיתים מספיק. וההצפנה חזקה מתמטית — אבל ״האדם״ חלש: פישינג, סיסמה חוזרת, וטלפון בלי עדכונים הם הדרך שבה באמת פורצים. אימות דו־שלבי בוואטסאפ (PIN) — ההגדרה החשובה ביותר שרוב האנשים לא הפעילו."},
// פסיכולוגיה
{c:"פסיכולוגיה",q:"מהי ״עומס קוגניטיבי״, ולמה ריבוי משימות הוא אשליה?",h:"המוח לא עושה שני דברים — הוא מחליף ביניהם.",a:"זיכרון העבודה מחזיק בערך 4 פריטים בו־זמנית. ״מולטיטסקינג״ הוא למעשה החלפה מהירה בין משימות, וכל החלפה גובה ״מס״ של שניות עד דקות ריכוז — במחקרים עד 40% מהזמן.",m:"חריג: משימה אוטומטית (הליכה) + משימה חושבת (שיחה). שתי משימות חושבות — לא.",d:"למה זה נוגע ללמידה כאן: לענות על שאלה עם טלפון פתוח על משהו אחר = הזיכרון לא נחקק. ובעבודה: כל התראה שנבדקת ״שנייה״ עולה ~20 דקות של חזרה לריכוז עמוק. הפתרון המוכח: בלוקים של 25–50 דקות עם התראות כבויות, ואז הפסקה אמיתית. אנשים שמרגישים ״טובים במולטיטסקינג״ הם במחקרים דווקא הגרועים ביותר בו."},
{c:"פסיכולוגיה",q:"מהי ״עקומת השכחה״ של אבינגהאוס, ואיך מנצחים אותה?",h:"האפליקציה הזו בנויה עליה.",a:"הרמן אבינגהאוס (1885) מדד שאנחנו שוכחים כמחצית ממה שלמדנו תוך יום, ורוב השאר תוך שבוע — אבל כל חזרה ברווח הולך וגדל (יום, שלושה, שבוע, חודש) משטחת את העקומה, עד שהידע יציב.",m:"״חזרה מרווחת״ + ״שליפה פעילה״ (לנסות להיזכר לפני שרואים תשובה) — שני העקרונות הכי מבוססים במדע הלמידה.",d:"למה ״לקרוא שוב״ מרגיש כאילו לומדים אבל לא עובד: קריאה חוזרת יוצרת ״שטף״ — הטקסט מוכר, והמוח מבלבל מוכרות עם ידיעה. שליפה (לכסות, לנסות לענות, רק אז לבדוק) קשה ומתסכלת יותר — וזה בדיוק המאמץ שחורט. לכן באפליקציה ״נסה לענות בראש לפני שתחשוף״ הוא לא נימוס; זה המנגנון."},
{c:"פסיכולוגיה",q:"מהי ״השפעת האחר״ (Bystander effect), ומה זה מלמד על עזרה במצבי חירום?",h:"ככל שיותר אנשים רואים — פחות סיכוי שמישהו יעזור.",a:"כשרבים נוכחים, האחריות ״מתפזרת״ וכל אחד מניח שמישהו אחר יפעל, ובנוסף כולם מסתכלים על כולם ורואים ״שקט״ — ומסיקים שאין חירום. תועד אחרי רצח קיטי ג׳נובזה (1964).",m:"הפתרון: להצביע על אדם ספציפי — ״אתה, בחולצה הכחולה, תתקשר 101״.",d:"למה זה חשוב לך כמי שמאבטח: בזירה עם 30 אנשים, אף אחד לא עושה כלום — לא כי אכפת להם פחות אלא בגלל המנגנון. מי שלוקח פיקוד עם הוראות שמיות קצרות (״אתה — דפיברילטור מהכניסה. את — הרחיקי אנשים״) שובר את השיתוק מיד. וגם על עצמך: אם אתה מהסס בגלל ש״אף אחד לא זז״ — זה בדיוק האפקט, ומספיק אדם אחד שזז כדי שכולם יצטרפו."},
{c:"פסיכולוגיה",q:"מהי ״דחיינות״ מבחינה פסיכולוגית — ולמה זה לא עצלנות?",h:"ניהול רגש, לא ניהול זמן.",a:"דחיינות היא הימנעות ממשימה שמעוררת רגש לא נעים (שעמום, חרדה מכישלון, חוסר ודאות) לטובת הקלה מיידית. המחקר מראה שהיא בעיית ויסות רגשי — הדוחים לא בהכרח מנהלים זמן גרוע.",m:"כלל 2 הדקות: אם זה לוקח פחות משתי דקות — עושים עכשיו. אם יותר — מתחילים ב־2 דקות.",d:"קשור ישירות לדפוס ״הרבה מיזמים, מעט ביצוע״: כל מיזם חדש מלהיב (דופמין של תכנון), והביצוע המשעמם/המפחיד של הישן דוחה. הטריק המבוסס: להקטין את הצעד הבא עד שהוא לא מעורר שום רגש (״לפתוח את הקובץ״, לא ״לסיים את התוכנית העסקית״), ולקבוע *מתי ואיפה* בדיוק (״כוונת יישום״ — מכפילה סיכויי ביצוע במחקרים)."},
{c:"פסיכולוגיה",q:"מהו ״ההבדל בין מוטיבציה פנימית לחיצונית״, ומהו ״אפקט ההצדקה היתרה״?",h:"תשלום יכול להרוג הנאה.",a:"פנימית — עושים כי מעניין/מהנה; חיצונית — בשביל פרס או מפחד עונש. אפקט ההצדקה היתרה: כשמתחילים לתגמל פעילות שאהבנו, המוח מסיק ״אני עושה את זה בשביל הפרס״ — וכשהפרס נעלם, גם המוטיבציה.",m:"ניסוי קלאסי: ילדים שקיבלו פרס על ציור — ציירו פחות אחר כך מאלה שלא קיבלו.",d:"שימוש נכון: תגמולים עובדים למשימות משעממות (מילוי טפסים), ומזיקים לדברים שאתה רוצה לאהוב לאורך זמן (למידה, אימון). לכן באפליקציה הזו ה״פרסים״ הם רצפים ופידבק ולא נקודות שקונים איתן משהו. ובניהול אנשים: בונוס על יצירתיות לרוב מוריד אותה; אוטונומיה, שליטה ומשמעות — מעלים."},
{c:"פסיכולוגיה",q:"מהי ״תשומת לב סלקטיבית״, ומה הראה ניסוי ״הגורילה הבלתי נראית״?",h:"ספרו מסירות — ופספסו גורילה.",a:"צופים שהתבקשו לספור מסירות כדור לא ראו אדם בתחפושת גורילה שחצה את המסך (כמחצית מהנבדקים). המוח מסנן כל מה שלא רלוונטי למשימה הנוכחית — ואנחנו לא מודעים לסינון.",m:"סימונס וצ׳אבריס, 1999. אותו מנגנון מסביר תאונות ״לא ראיתי את האופנוע״.",d:"למה זה חומר ליבה בשמירה ובאבטחה: אדם שממוקד במשימה אחת (בדיקת תיקים) עיוור למה שקורה מטר לידו. לכן עמדות אבטחה בנויות עם ״עיניים״ נפרדות לסריקה כללית, ולכן שוטרים מאומנים לסרוק ידיים ולא פנים. ובנהיגה: ״הסתכלתי ולא ראיתי״ הוא אמיתי — המוח מחפש מכוניות ולא רואה אופניים. הפתרון: לשאול את עצמך במפורש ״מה אני *לא* מחפש עכשיו?״."},
{c:"פסיכולוגיה",q:"מהי ״חוסר ישע נלמד״, ומה ההפך שלו?",h:"כלבים שהפסיקו לנסות לברוח.",a:"סליגמן (1967): בעלי חיים שנחשפו לשוק חשמלי שאי אפשר להימנע ממנו — הפסיקו לנסות גם כשכבר יכלו. אצל בני אדם: אחרי סדרת כישלונות ״שלא בשליטה״, מפסיקים לפעול גם כשיש שליטה. ההפך: ״אופטימיות נלמדת״ — לייחס כישלון לגורמים זמניים וספציפיים, לא קבועים וכלליים.",m:"סגנון ההסבר (״אני כישלון״ מול ״הניסיון הזה נכשל בגלל X״) מנבא דיכאון, ביצועים בספורט ובמכירות.",d:"הדוגמה מהאפליקציה: אם אחרי 5 שאלות שגויות אומרים ״אין לי זיכרון״ — זה ייחוס קבוע וכללי, והמוח מפסיק להתאמץ. ״הקטגוריה הזו עדיין חדשה לי״ — זמני וספציפי, ואפשר לפעול. סליגמן טען שאפשר לאמן את הסגנון הזה במודע: לתפוס את המשפט האוטומטי, ולנסח אותו מחדש עם ראיות."},
{c:"פסיכולוגיה",q:"מהי ״אפקט הזייגרניק״, ולמה משימות פתוחות מציקות?",h:"המלצר זוכר את ההזמנה רק עד שהיא שולמה.",a:"בלומה זייגרניק (שנות ה־20) הבחינה שמלצרים זוכרים הזמנות פתוחות ושוכחים אותן מיד אחרי התשלום. משימות לא גמורות ״נשארות פתוחות״ במוח וצורכות קשב — עד שסוגרים אותן, או לפחות מתכננים בבירור מתי.",m:"מחקרים הראו שכתיבת תוכנית קונקרטית למשימה פתוחה מפסיקה את ההטרדה כמעט כמו ביצועה.",d:"מכאן ״ריקון המוח״: רשימה אחת שבה כל מיזם/מטלה פתוח נמצא עם *הצעד הבא* שלו. המוח משחרר, כי הוא סומך על המערכת. וזה הפוך מרשימת ״רעיונות למיזמים״ בלי צעד — כזו רשימה רק מגדילה את הרעש. סדרות טלוויזיה, בדרך אגב, מנצלות את זה עם קליפהנגרים — הפרק לא ״נסגר״, אז ממשיכים."},
{c:"פסיכולוגיה",q:"מהי ״הסתגלות הדונית״ (Hedonic adaptation)?",h:"הלוטו לא ישמח אותך לאורך זמן — וגם הפציעה לא תשבור.",a:"הנטייה לחזור לרמת אושר בסיסית אחרי אירועים טובים ורעים. במחקר המפורסם, זוכי לוטו ונפגעי שיתוק דיווחו כעבור שנה על רמות אושר קרובות להפתיע. רכישות ושדרוגים ״נשחקים״ תוך שבועות.",m:"מה שנשחק פחות: חוויות, קשרים, ושינויים שמשתנים (גיוון) ולא סטטיים.",d:"ההשלכה על יעד ״עצמאות כלכלית״: הרמה שבה ״מספיק״ בורחת עם כל עלייה בהכנסה, אלא אם קובעים אותה מראש ובמספר. גם שדרוג רכב/דירה/טלפון — 3 שבועות של הנאה ואז זה ״הרגיל״ החדש. מה שעובד נגד ההסתגלות: לפזר שדרוגים קטנים ולא לקפוץ קפיצות, לעצור לרגע ולשים לב למה שכבר יש, ולהוציא על זמן וחוויות עם אנשים."},
{c:"פסיכולוגיה",q:"מהו ״אפקט פיגמליון״?",h:"הציפייה יוצרת את התוצאה.",a:"רוזנטל וג׳ייקובסון (1968): מורים שנאמר להם (באקראי) שתלמידים מסוימים ״עומדים לפרוח״ — התלמידים האלה באמת שיפרו ציוני IQ. ציפיות משפיעות על יחס עדין (זמן, סבלנות, חום) שמשפיע על ביצועים.",m:"ההפך — ״אפקט גולם״: ציפייה נמוכה מורידה ביצועים.",d:"רלוונטי לניהול צוות שמירה, לאימון בת הזוג, ולעצמך: ״הוא לא ילמד״ הופך לנבואה, כי מקצרים הסברים ונותנים פחות הזדמנויות. ומצד שני — הצהרות בסגנון ״אתה גאון״ פוגעות (״הלך רוח קבוע״ של קרול דואק); ״התאמצת וזה עבד״ — משפרות. הציפייה שעובדת היא על *יכולת להתפתח*, לא על כישרון קבוע."},
{c:"פסיכולוגיה",q:"מהו ״תרגול מכוון״ (Deliberate practice), ולמה 10,000 שעות זה מיתוס חלקי?",h:"לא כמה — איך.",a:"אנדרס אריקסון: מומחיות נבנית מתרגול ממוקד בגבול היכולת, עם משוב מיידי ותיקון — לא מחזרה על מה שכבר יודעים. ״10,000 שעות״ הוא ממוצע שגלדוול פישט; באזורים שונים המספר משתנה מאוד, ושעות בלי משוב לא נספרות.",m:"נהג עם 20 שנות ניסיון לא בהכרח נוהג טוב מאחד עם 5 — הוא פשוט חוזר על מה שהוא יודע.",d:"התרגום לאפליקציה הזו: הכפתור ״חיזוק נקודות חלשות״ הוא תרגול מכוון; סבב של שאלות שאתה כבר יודע הוא לא. הרגשת הקושי היא הסימן שאתה במקום הנכון — הזיכרון מתחזק דווקא כשהשליפה כמעט נכשלת (״קשיים רצויים״, ביורק). זה נכון גם לאימון גופני: הסטים שבסופם כמעט נכשלים הם הסטים שבונים."},
{c:"פסיכולוגיה",q:"מהי ״הצטרפות למחויבות״ (Commitment & consistency), ואיך מנצלים אותה במכירות?",h:"רגל בדלת.",a:"אחרי שאמרנו ״כן״ לדבר קטן, אנחנו נוטים להסכים לדבר גדול כדי להישאר עקביים עם הדימוי העצמי. טכניקת ״רגל בדלת״: בקשה זעירה ואז הגדולה. (צ׳אלדיני, ״השפעה״.)",m:"ההפך — ״דלת בפרצוף״: בקשה מוגזמת שנדחית, ואז הבקשה ה״סבירה״ שהיא באמת מה שרצו.",d:"איפה תפגוש את זה: ״רק תשאיר טלפון״ → ״רק פגישה קצרה״ → מכירה. ״ניסיון חינם — רק תכניס כרטיס״. ובעצמך: הצהרה פומבית על מטרה (״אני מסיים את הקורס עד דצמבר״) מגייסת את אותו מנגנון לטובתך — לכן מחויבות בפני שותף עובדת. וגם הצד האפל: ״עלות שקועה״ + ״עקביות״ מסבירים למה אנשים נשארים בהשקעה גרועה — ״כבר השקעתי, לא אני אהיה זה שוויתר״."},
// כלכלה בפועל
{c:"כלכלה",q:"מהו מס רווחי הון בישראל, ומה ההבדל בין ״ריאלי״ ל״נומינלי״?",h:"25 אחוז — אבל על מה?",a:"25% על הרווח הריאלי (הרווח בניכוי האינפלציה) בניירות ערך ובקרנות; 15% על הרווח הנומינלי באפיקים לא צמודים (פיקדונות שקליים, אג״ח לא צמוד). המס נגבה אוטומטית על ידי הבנק/הברוקר הישראלי.",m:"הפסדים ניתנים לקיזוז מול רווחים — גם משנים קודמות (עם דיווח).",d:"למה ״ריאלי״ עוזר לך: קנית ב־100,000, מכרת ב־120,000 אחרי שנתיים עם 5% אינפלציה כוללת — הרווח הריאלי הוא ~15,000, לא 20,000, והמס ~3,750 ולא 5,000. ולמה ברוקר זר (IBKR וכד׳) שונה: הוא לא מנכה מס לישראל — אתה חייב בדיווח שנתי, וזה מקום שאנשים נופלים בו. קרן השתלמות — 0% על הכל, לכן היא האפיק הראשון שממלאים."},
{c:"כלכלה",q:"מהי ״ריבית אפקטיבית״ (APR), ולמה ״ריבית 1% לחודש״ זה לא 12% בשנה?",h:"ריבית דריבית עובדת גם נגדך.",a:"ריבית שמצטברת מדי חודש על הקרן + הריבית הקודמת — 1% לחודש = 12.68% בשנה. חוק מחייב לציין ריבית שנתית מתואמת, אבל פרסומות מבליטות את החודשית או את ה״החזר החודשי״.",m:"״החזר של רק 300 ₪ לחודש״ — תמיד להכפיל במספר החודשים ולהשוות לסכום שקיבלת.",d:"דוגמה מהחיים: הלוואה של 20,000 ₪ ב־״0.9% לחודש״ ל־36 חודשים. שנתי אפקטיבי: 11.4%. סה״כ החזר: כ־23,800 ₪ — כלומר שילמת 3,800 ₪ על הכסף. תשלומים ״קרדיט״ בכרטיס — לעיתים 10–17% שנתי. הלוואה מהבנק לפי דירוג טוב — פריים + 1–3%. אותו סכום, פער של אלפים. תמיד לבקש את ה״ריבית השנתית המתואמת״ בכתב."},
{c:"כלכלה",q:"מהו ״שיעור חיסכון״, ולמה הוא חשוב יותר מהתשואה בשנים הראשונות?",h:"בהתחלה מה שאתה שם חשוב יותר ממה שהשוק עושה.",a:"האחוז מההכנסה נטו שנשאר ולא מוצא. בעשור הראשון של חיסכון, ההפקדות עצמן הן רוב הצמיחה — תשואה של 7% על 50,000 ₪ היא 3,500, אבל עוד 2,000 ₪ הפקדה בחודש זה 24,000 בשנה. רק כשההון גדול התשואה מתחילה ״לעבוד״.",m:"כלל אצבע ל־FIRE (עצמאות כלכלית): שיעור חיסכון של 50% מקצר את הדרך לעצמאות ל־~17 שנה; 20% — ל־~37.",d:"החישוב שמסביר את זה: עצמאות כלכלית ≈ הון של 25 × הוצאה שנתית (״כלל ה־4%״). מי שחי על 8,000 ₪ בחודש צריך ~2.4 מיליון; מי שחי על 12,000 — 3.6 מיליון. כלומר כל 1,000 ₪ שמורידים מההוצאה הקבועה זה 300,000 ₪ פחות שצריך *וגם* עוד 12,000 בשנה לחיסכון. לכן ההוצאה הקבועה (שכ״ד, רכב, מנויים) היא המנוף הגדול, לא הקפה."},
{c:"כלכלה",q:"מהי ״קרן חירום״, ולמה היא קודמת להשקעות?",h:"3–6 חודשי הוצאות בצד.",a:"סכום נזיל (פיקדון/קרן כספית) שמכסה 3–6 חודשי הוצאות. המטרה: שהוצאה פתאומית או אובדן הכנסה לא יכריחו אותך למכור השקעות בזמן גרוע או לקחת הלוואה יקרה.",m:"למי שיש הכנסה לא יציבה או עצמאי — קרוב ל־6 ויותר; לשכיר עם פנסיה ומילואים — 3–4 מספיקים לרוב.",d:"למה זה עניין של תשואה ולא של פחד: מי שבלי קרן חירום מוכר מניות בירידה של 30% כדי לשלם על תיקון רכב — ״נעל״ הפסד שיקח שנים להשלים. קרן החירום היא ה״ביטוח״ שמאפשר לשאר הכסף להישאר מושקע דרך המשברים. ואיפה שמים: קרן כספית (נזילה, ~ריבית בנק ישראל, מס 25% ריאלי בלבד) עדיפה על עו״ש שנשחק באינפלציה."},
{c:"כלכלה",q:"מהו ״דירוג אשראי״ בישראל, ואיך הוא נבנה?",h:"מאז 2019 יש מאגר.",a:"מ־2019 בנק ישראל מנהל מאגר נתוני אשראי: הבנקים וחברות האשראי מדווחים על הלוואות, מסגרות, פיגורים וצ׳קים חוזרים. חברות דירוג (למשל BDI, דן אנד ברדסטריט) מחשבות ממנו ציון. ציון גבוה = ריבית נמוכה יותר על הלוואות ומשכנתא.",m:"אפשר לבקש את הדו״ח האישי חינם דרך אתר בנק ישראל, ולבקש ״לא לאסוף״ נתונים — אבל אז אין לך דירוג.",d:"מה מוריד ציון: פיגור בתשלום מעל 30 יום, חריגה ממסגרת, צ׳ק חוזר, הרבה בקשות הלוואה בזמן קצר. מה בונה אותו: הלוואה קטנה שמשולמת במועד, שימוש במסגרת אשראי בלי לחרוג. לפני משכנתא — לבדוק את הדו״ח שנה מראש: טעות בדיווח (הלוואה שנסגרה ומופיעה פתוחה) יכולה לעלות עשרות אלפי שקלים בריבית לאורך המשכנתא, וניתן לתקן אותה."},
{c:"כלכלה",q:"מהי ״עלות אלטרנטיבית״?",h:"המחיר האמיתי של כל בחירה הוא מה שוויתרת עליו.",a:"הערך של האפשרות הטובה ביותר שוויתרת עליה כשבחרת. כסף בפיקדון של 4% ״עולה״ לך את ה־8% שהיה יכול לעשות במניות; שנה של הכנות למיזם ״עולה״ את ההכנסה שהיית מרוויח בינתיים.",m:"מונח־ליבה בכלכלה: ״אין ארוחות חינם״ — כל משאב (זמן, כסף, קשב) יש לו שימוש חלופי.",d:"החישוב שאנשים לא עושים: ״קניתי רכב ב־80,000 ₪ במזומן, אין לי הלוואה — חינם״. לא: 80,000 בהשקעה ב־7% הם 5,600 ₪ בשנה, כלומר 470 ₪ בחודש שהרכב ״עולה״ בלי שראית תשלום. אותו הדבר על זמן: שעה של ״לחסוך 30 ₪״ בנסיעה לחנות זולה יותר היא הפסד אם שעת העבודה שלך שווה 60. שאלה לכל החלטה: ״מה הדבר הכי טוב שאני *לא* עושה בגלל זה?״"},
];
Q.push(...EXP20B);

/* ================= שכבה 20ג — עולם היום + מדע + היסטוריה + גאוגרפיה ================= */
const EXP20C=[
// עולם היום
{c:"עולם היום",q:"מהי מועצת הביטחון של האו״ם, ומי חמש החברות הקבועות?",h:"המנצחות במלחמת העולם השנייה.",a:"הגוף היחיד באו״ם שהחלטותיו מחייבות. 15 חברות: 5 קבועות עם זכות וטו — ארה״ב, רוסיה, סין, בריטניה, צרפת — ו־10 מתחלפות לשנתיים.",m:"וטו של חברה קבועה אחת מפיל כל החלטה — לכן המועצה משותקת ברוב הסכסוכים בין המעצמות.",d:"למה זה משנה לישראל: ארה״ב הטילה וטו על עשרות החלטות נגד ישראל — זו ״המטרייה״ המדוברת. החלטה 2334 (2016) עברה כי ארה״ב נמנעה. לעומת המועצה, החלטות העצרת הכללית (193 מדינות) הן המלצות בלבד — לכן ״רוב אוטומטי נגד ישראל״ בעצרת מייצר כותרות ולא סנקציות."},
{c:"עולם היום",q:"מהו נאט״ו, ומהו סעיף 5?",h:"תקיפה על אחד = תקיפה על כולם.",a:"ברית צבאית שנוסדה ב־1949 מול ברית המועצות; היום 32 מדינות. סעיף 5 באמנה: תקיפה מזוינת על חברה אחת נחשבת תקיפה על כולן. הופעל פעם אחת בלבד — אחרי 11 בספטמבר.",m:"פינלנד (2023) ושוודיה (2024) הצטרפו בעקבות הפלישה לאוקראינה — ההפך ממה שפוטין רצה.",d:"למה אוקראינה לא בנאט״ו וזה כל הסיפור: הצטרפות דורשת הסכמה של כל החברות, ומדינה במלחמה פעילה לא תתקבל — כי סעיף 5 היה מכניס את הברית כולה למלחמה עם רוסיה. הדרישה של 2% מהתמ״ג לביטחון (טראמפ דחף ל־5%) היא הוויכוח הפנימי הקבוע. ישראל אינה חברה — ״שותפה עיקרית שאינה חברה״ בברית עם ארה״ב."},
{c:"עולם היום",q:"מהו האיחוד האירופי, ומה ההבדל בינו לגוש האירו ולאזור שנגן?",h:"שלושה מעגלים שלא חופפים.",a:"האיחוד: 27 מדינות עם שוק משותף וחקיקה משותפת. גוש האירו: 20 מהן שמשתמשות באירו (לא פולין, שוודיה, צ׳כיה…). שנגן: 29 מדינות בלי ביקורת גבולות ביניהן — כולל שווייץ ונורווגיה שאינן באיחוד, ולא כולל אירלנד.",m:"בריטניה עזבה ב־2020 (ברקזיט) — המדינה היחידה שעזבה אי פעם.",d:"מה זה עושה לך כתייר: בשנגן שוהים עד 90 יום מתוך 180 ללא ויזה — הספירה משותפת לכל המדינות (90 יום ביוון + צרפת + איטליה יחד, לא כל אחת). מ־2025–26 נכנסות מערכות EES (רישום ביומטרי) ו־ETIAS (אישור מראש ב־7 אירו) גם לישראלים. ומיסים: ״טקס פרי״ עובד על יציאה מהאיחוד כולו, לא מכל מדינה."},
{c:"עולם היום",q:"מהו ה־G7 ומהו ה־G20?",h:"העשירות, והגדולות.",a:"G7: פורום של 7 כלכלות מפותחות — ארה״ב, יפן, גרמניה, בריטניה, צרפת, איטליה, קנדה (+ האיחוד האירופי). G20: 19 המדינות הגדולות + האיחוד האירופי + האיחוד האפריקאי — כ־85% מהתמ״ג העולמי, כולל סין, הודו, ברזיל, סעודיה, טורקיה.",m:"רוסיה סולקה מה־G8 ב־2014 אחרי סיפוח קרים — כך חזרו ל־G7.",d:"ה־G20 הוא המקום שבו באמת קורים דברים בכלכלה גלובלית (למשל מס חברות מינימלי עולמי של 15%), כי סין והודו בפנים. ה־BRICS (ברזיל, רוסיה, הודו, סין, דרום אפריקה + מ־2024 גם איראן, מצרים, אתיופיה, איחוד האמירויות) הוא הניסיון של ״הדרום הגלובלי״ לבנות משקל נגד למערב — כולל דיבור על מטבע חלופי לדולר, שעד כה נשאר דיבור."},
{c:"עולם היום",q:"למה השקל נחלש כשהבורסה בארה״ב יורדת — ומה עוד מזיז את הדולר/שקל?",h:"ריבית, ביטחון, ובורסה אמריקאית.",a:"המחיר של דולר בשקלים. מתחזק (השקל נחלש) כשיש אי־ודאות ביטחונית/פוליטית, כשריבית הדולר גבוהה מהשקל, וכשהבורסה בארה״ב יורדת (הגופים המוסדיים הישראליים קונים דולרים לגידור). מתחזק שקל: עודף בייצוא הייטק וגז, זרם השקעות זרות.",m:"בנק ישראל מחזיק ~200 מיליארד דולר רזרבות ויכול להתערב בשוק — עשה זאת באוקטובר 2023.",d:"למה כדאי לחשוב ״בשני מטבעות״: הוצאות שלך בשקלים, אבל רוב ההשקעות בעולם (S&P) בדולרים — כשהשקל מתחזק התיק ״יורד״ בשקלים גם אם השוק עלה. קרנות ״מנוטרלות מט״ח״ מבטלות את זה במחיר עלות קטנה. לטיול ביפן: לשלם בכרטיס במטבע המקומי (ין), לא לקבל את ה״המרה״ של המסוף — היא תמיד יקרה ב־3–5%."},
{c:"עולם היום",q:"מהי ״שרשרת האספקה״, ומה גילה משבר הקורונה עליה?",h:"ספינה אחת בתעלה תקעה את העולם.",a:"רשת הייצור והובלה הגלובלית: רכיב מטייוואן, הרכבה בסין, מכולה דרך סואץ, מחסן באירופה. ״בדיוק בזמן״ (JIT) — מלאי מינימלי — הוזיל הכל אבל התברר שביר: סגר במפעל אחד או ספינה תקועה (Ever Given, 2021) עוצרים מפעלים ביבשת אחרת.",m:"מחסור השבבים 2021–22 עצר פסי ייצור של רכב בכל העולם — בגלל רכיבים שעולים דולרים בודדים.",d:"למה זה מסביר גאופוליטיקה של היום: 90% מהשבבים המתקדמים בעולם מיוצרים בטייוואן (TSMC) — לכן פלישה סינית לטייוואן היא סיכון לכלכלה העולמית כולה, לא רק לאי. ארה״ב מסבסדת מפעלי שבבים בבית (CHIPS Act), ״פרנד־שורינג״ (העברת ייצור למדינות ידידותיות) הפך למונח. והחות׳ים בים האדום 2023–24 הראו שמעבר ימי אחד יכול לייקר הובלה פי 3."},
{c:"עולם היום",q:"מהי ״האינטרנט של סין״ ומהי ״חומת האש הגדולה״?",h:"אין גוגל, אין וואטסאפ — ויש חלופה לכל דבר.",a:"סין חוסמת גוגל, פייסבוק, יוטיוב, וויקיפדיה ואלפי אתרים, ומסננת תוכן בזמן אמת. במקומם אקוסיסטם מקומי: WeChat (הכל באפליקציה אחת), Baidu, Weibo, Douyin (הגרסה הסינית של טיקטוק). VPN אפשרי אבל לא חוקי רשמית.",m:"WeChat: הודעות, תשלומים, תורים לרופא, קנסות — 1.3 מיליארד משתמשים.",d:"למה זה חשוב מעבר לסין: המודל ״ריבונות דיגיטלית״ מיוצא לרוסיה, איראן ומדינות נוספות; ומצד שני טיקטוק, שיאומי ורכבי BYD הם הפעם הראשונה שסין מייצאת מותגי צרכנות שהמערב רוצה. הוויכוח על טיקטוק בארה״ב הוא בדיוק על זה: מי מחזיק את הנתונים ואת האלגוריתם שמעצב מה 170 מיליון אמריקאים רואים."},
{c:"עולם היום",q:"מהי הפדרל ריזרב לעומת בנק ישראל, ולמה ריבית בארה״ב משפיעה על המשכנתא שלך?",h:"כשוושינגטון מתעטשת.",a:"שניהם בנקים מרכזיים — קובעים ריבית ומנהלים את כמות הכסף. הפד קובע את מחיר הדולר, המטבע העולמי; כשריבית הדולר עולה, כסף בורח ממטבעות אחרים לדולר, השקל נחלש, יבוא מתייקר — ובנק ישראל מעלה ריבית כדי לא להישאר מאחור. ריבית בנק ישראל = ריבית הפריים (+1.5%) = הריבית על המשכנתא במסלול הפריים.",m:"פריים = ריבית בנק ישראל + 1.5%. זו הנוסחה שכל לווה צריך לדעת.",d:"החישוב שמראה את הקשר: משכנתא של מיליון ₪ ל־25 שנה, שליש במסלול פריים. ריבית בנק ישראל עלתה מ־0.1% (2021) ל־4.75% (2023) — הפריים מ־1.6% ל־6.25% — ההחזר על שליש הפריים קפץ ב־~800 ₪ בחודש. לכן ״לפני שלוקחים משכנתא — לבדוק לאן הפד הולך״ זה לא ייעוץ אקזוטי."},
{c:"עולם היום",q:"מהו ״הסכמי אברהם״, ומה הם שינו?",h:"2020 — ארבע מדינות בכמה חודשים.",a:"הסכמי נורמליזציה בין ישראל לאיחוד האמירויות ובחריין (ספטמבר 2020), ואחריהם סודאן ומרוקו. השינוי: לראשונה מדינות ערביות חתמו על שלום בלי לקשור אותו לפתרון הסוגיה הפלסטינית תחילה.",m:"טיסות ישירות לדובאי, סחר של מיליארדים, ושיתופי פעולה ביטחוניים נגד איראן — הכל תוך שנים ספורות.",d:"למה סעודיה היא ״הפרס הגדול״: היא שומרת המקומות הקדושים לאסלאם, ונורמליזציה איתה הייתה פותחת את רוב העולם המוסלמי. המשא ומתן היה מתקדם ערב 7 באוקטובר 2023 — ורבים רואים במתקפה ניסיון לטרפד אותו. הדרישה הסעודית מאז: מסלול למדינה פלסטינית + ברית ביטחונית עם ארה״ב + גרעין אזרחי."},
{c:"עולם היום",q:"מהם ״הצירים״ הגאופוליטיים המרכזיים היום, במשפט אחד לכל אחד?",h:"ארבעה סכסוכים שמעצבים את העולם.",a:"ארה״ב–סין: תחרות טכנולוגית וכלכלית עם טייוואן כנקודת הצתה. רוסיה–המערב: מלחמת אוקראינה (מ־2022). איראן ושלוחותיה (חיזבאללה, חות׳ים, מיליציות) מול ישראל ומדינות המפרץ. והמאבק על ״הדרום הגלובלי״ — הודו, אפריקה, דרום אמריקה — מי ישפיע עליהם.",m:"״הציר״ — רוסיה, סין, איראן, צפון קוריאה — מחליפות נשק, נפט וטכנולוגיה, אבל אינן ברית פורמלית.",d:"למה כדאי לחשוב על זה כרשת ולא כסיפורים נפרדים: מל״טים איראניים באוקראינה, נפט רוסי מוזל לסין והודו, פגזים מצפון קוריאה לרוסיה, שבבים אמריקאיים שנחסמים לסין — כל חזית מזינה את האחרת. וישראל יושבת בדיוק על התפר: בעלת ברית של ארה״ב, סוחרת גדולה עם סין, ובעימות ישיר עם הציר האיראני."},
// מדע
{c:"מדע",q:"מהו ״גז חממה״, ואיך CO₂ מחמם את כדור הארץ?",h:"שמיכה שמעבירה אור אבל עוצרת חום.",a:"אור השמש נכנס ומחמם את הקרקע; הקרקע פולטת חום כקרינה אינפרה־אדומה; מולקולות כמו CO₂, מתאן ואדי מים בולעות חלק מהאינפרה־אדום ומחזירות אותו מטה. בלי אפקט החממה — ממוצע של −18° במקום +15°. הבעיה היא העודף.",m:"ריכוז CO₂ עלה מ־280 חלקים למיליון לפני המהפכה התעשייתית ל־420+ היום — הגבוה ב־3 מיליון שנה.",d:"למה מתאן חשוב אף שיש ממנו פחות: מולקולה של מתאן לוכדת פי ~80 יותר חום מ־CO₂ ב־20 שנה (אבל מתפרקת אחרי ~12 שנה). מקורות: בקר, מאגרי גז דולפים, מזבלות. לכן איטום דליפות בשדות גז הוא ״הניצחון המהיר״ בעולם האקלים. וישראל: 100 ק״מ מהים בקיץ 2023 נמדדו טמפרטורות מים של 32° — הים התיכון מתחמם ב־20% מהר יותר מהממוצע העולמי."},
{c:"מדע",q:"מהי קרינה מייננת, ומה ההבדל בינה לקרינה סלולרית?",h:"רנטגן כן, וויי־פיי לא.",a:"מייננת — אנרגיה מספיקה לעקור אלקטרונים מאטומים ולשבור DNA: רנטגן, גמא, UV קצר, חלקיקי אלפא/בטא. לא־מייננת — רדיו, סלולר, וויי־פיי, מיקרוגל, אור נראה: יכולה לחמם, לא לשבור קשרים כימיים.",m:"השמש היא מקור הקרינה המייננת הנפוץ ביותר שאנחנו נחשפים לו — UV גורם לרוב סרטני העור.",d:"מספרים שמסדרים את הפחדים: צילום חזה ≈ 0.1 מיליסיוורט; CT בטן ≈ 10; טיסה טרנס־אטלנטית ≈ 0.05; קרינת רקע שנתית טבעית בישראל ≈ 2–3. סלולר — אפס מייננת, וה־WHO מסווג אותו ״אפשרי״ (2B, אותה קטגוריה כמו ירקות כבושים) על סמך מחקרים לא עקביים. הדבר האחד שכן מוכח: קרם הגנה."},
{c:"מדע",q:"מהי אנטרופיה, במילים פשוטות?",h:"למה חדר מתבלגן לבד ולא מסתדר לבד.",a:"מדד לאי־סדר או למספר הדרכים שבהן מערכת יכולה להיות מסודרת. החוק השני של התרמודינמיקה: במערכת סגורה האנטרופיה תמיד עולה — חום זורם מחם לקר, לא להפך, וזה מה שמגדיר את ״כיוון הזמן״.",m:"אפשר להוריד אנטרופיה מקומית (מקרר, חיים) — רק על ידי הגדלתה במקום אחר (חום שהמקרר פולט).",d:"למה זה עמוק באמת: זו הסיבה שאין מנוע ״נצחי״, שאי אפשר להפוך ביצה מקושקשת חזרה, ושהיקום ״מתבלה״. וחיים הם התופעה המדהימה של מערכות שמחזיקות סדר גבוה — על ידי שריפת אנרגיה (אוכל, שמש) ופליטת חום. גם דירה, גוף וחשבון בנק מצייתים לאותו חוק: הסדר דורש עבודה מתמדת; הבלגן קורה לבד."},
{c:"מדע",q:"איך יודעים בן כמה מאובן או ממצא ארכיאולוגי?",h:"פחמן 14 — עד 50 אלף שנה.",a:"תיארוך פחמן־14: יצורים חיים קולטים פחמן רדיואקטיבי מהאוויר; מרגע המוות הוא דועך בקצב ידוע (מחצית כל 5,730 שנה). היחס שנשאר = גיל. תקף עד ~50,000 שנה. לגיל גאולוגי (מיליוני שנים) — יסודות איטיים יותר (אורניום־עופרת, אשלגן־ארגון) בשכבות הסלע.",m:"מגילות ים המלח תוארכו כך למאות 3–1 לפנה״ס — ותאמו את הכתב.",d:"למה זה עובד עם ״עקומת כיול״: ריכוז ה־C14 באטמוספרה לא היה קבוע לחלוטין (שמש, ניסויים גרעיניים בשנות ה־50 הכפילו אותו), לכן משווים לטבעות עצים ידועות. ובמזרח התיכון זו הבמה: הוויכוח על גיל חומות ירושלים או ״ממלכת דוד״ הוא לעיתים ויכוח של 50 שנה בתיארוך — ההבדל בין המקרא כהיסטוריה לבין סיפור מאוחר."},
{c:"מדע",q:"מהו pH, ולמה ״מי לימון״ לא ״מבסיסים את הגוף״?",h:"7 זה ניטרלי. הדם שלך תמיד 7.4.",a:"סולם חומציות 0–14: מתחת ל־7 חומצי (לימון ~2, קיבה ~1.5), מעל 7 בסיסי (סבון ~10). הדם נשמר ב־7.35–7.45 בקפדנות על ידי הריאות והכליות — סטייה קטנה היא מצב חירום. אוכל לא משנה את pH הדם; רק את השתן.",m:"״דיאטה בסיסית״ — אין לה בסיס מדעי מעבר לכך שירקות בריאים ממילא.",d:"איפה pH כן משנה בחיים: שיניים — אמייל מתחיל להתמוסס מתחת ל־5.5, ולכן משקאות חומציים (קולה 2.5, גם ״דיאט״) ולגימת לימון עם מים כל היום שוחקים שיניים. אחרי חומצי — לא לצחצח מיד (האמייל רך) אלא לשטוף במים ולחכות 30 דקות. ובים: מי האוקיינוס ירדו מ־8.2 ל־8.1 בגלל CO₂ — ״החמצת האוקיינוסים״, שממיסה שלדי אלמוגים."},
// היסטוריה
{c:"היסטוריה",q:"מה היה משבר הטילים בקובה, ומה למדו ממנו?",h:"13 ימים באוקטובר 1962.",a:"ברית המועצות הציבה טילים גרעיניים בקובה, 150 ק״מ מפלורידה. קנדי הטיל סגר ימי; העולם היה הכי קרוב אי פעם למלחמה גרעינית. נפתר בהסכם: הסובייטים מוציאים את הטילים, ארה״ב מתחייבת לא לפלוש לקובה ומוציאה (בסתר) טילים מטורקיה.",m:"בעקבותיו הוקם ״הקו האדום״ — קו טלפון ישיר בין וושינגטון למוסקבה.",d:"הלקח שמלמדים בכל קורס קבלת החלטות: קנדי דחה את היועצים שדרשו תקיפה מיידית (״האם אנחנו יודעים מה קורה אחרי הצעד השני?״), הקים צוות קטן שדן בחלופות במקום בחדר גדול שבו כולם מסכימים עם הבכיר, והשאיר ליריב ״דרך לרדת מהעץ״ בכבוד. ומאחורי הקלעים: קצין צוללת סובייטי אחד, וסילי ארכיפוב, סירב לאשר שיגור טורפדו גרעיני — ובזה כנראה מנע את הסוף."},
{c:"היסטוריה",q:"מהי המהפכה התעשייתית, ולמה היא התחילה דווקא בבריטניה?",h:"פחם, קיטור, וכסף.",a:"המעבר מייצור ידני וחקלאי לייצור במכונות ובמפעלים, מסוף המאה ה־18. בריטניה: פחם זמין, מנוע הקיטור (ואט, 1776), קולוניות לחומרי גלם ושווקים, מערכת בנקאות ופטנטים, וחקלאות שהתייעלה ושחררה ידיים לעבודה.",m:"במאה שלאחר מכן ההכנסה לנפש בבריטניה עלתה יותר מאשר ב־2,000 השנים הקודמות יחד.",d:"למה זה הרגע החשוב ביותר בהיסטוריה הכלכלית: עד 1800 רוב האנושות חיה על סף קיום כמו ב־3000 לפנה״ס. הגרף של התמ״ג לנפש הוא קו שטוח שמזנק פתאום. כל מה שאתה מכיר — מזון בשפע, תוחלת חיים 80, מעמד ביניים — נולד שם. וגם הצד השני: עבודת ילדים, ערי פיח, ופליטת הפחמן שאנחנו משלמים עליה היום."},
{c:"היסטוריה",q:"מהי שואת יהודי אירופה במספרים ובשלבים העיקריים?",h:"1933 → 1941 → 1945.",a:"1933 עליית הנאצים והחקיקה הגזעית (חוקי נירנברג 1935); 1938 ליל הבדולח; 1939–41 גטאות בפולין; יוני 1941 — עם פלישה לברית המועצות — הרצח ההמוני בירי (״השואה בכדורים״, ~1.5 מיליון); ועידת ואנזה (ינואר 1942) ומחנות ההשמדה (אושוויץ, טרבלינקה, בלז׳ץ, סוביבור, חלמנו, מיידנק). כ־6 מיליון נרצחו — שני שלישים מיהדות אירופה.",m:"1.5 מיליון מהנרצחים היו ילדים.",d:"עובדות שמפתיעות גם ישראלים: רוב הנרצחים לא מתו באושוויץ אלא בבורות ירי במזרח ובמחנות ״מבצע ריינהרד״ בפולין; שיא ההשמדה היה בשלושה חודשים בסתיו 1942 (כ־1.3 מיליון). ומה שרלוונטי לזיכרון: ההתנגדות — מרד גטו ורשה (אפריל 1943), מרד סוביבור, הפרטיזנים — וגם ״חסידי אומות העולם״, כ־28,000 שהוכרו ביד ושם."},
{c:"היסטוריה",q:"מהי ״הקונספציה״ של 1973, ולמה המילה חזרה ב־2023?",h:"6 באוקטובר 1973, 14:00.",a:"מתקפת פתע מצרית־סורית ביום כיפור. המחדל: המודיעין ידע על ההיערכות אך ״הקונספציה״ קבעה שמצרים לא תתקוף בלי עליונות אווירית — והמילואים גויסו מאוחר. אחרי ימים קשים צה״ל צלח את התעלה וכיתר את הארמייה השלישית; הפסקת אש ב־24 באוקטובר. ~2,650 חללים.",m:"ועדת אגרנט הדיחה את הרמטכ״ל והראש אמ״ן; גולדה ודיין התפטרו בלחץ ציבורי. הובילה עקיפין להסכם השלום עם מצרים (1979).",d:"למה ״קונספציה״ הפכה למילה שכל ישראלי מכיר: כשמניחים שהיריב ״לא יעז״ — כל התרעה מתפרשת דרך ההנחה במקום לערער אותה. הקבלה ל־7 באוקטובר 2023 (ההנחה שחמאס ״מורתע״) נעשתה מיד. הלקח המקצועי: מודיעין צריך ״פרקליט השטן״ — יחידה שתפקידה לטעון את ההפך מהקונספציה. הוקמה אחרי 73׳ (״מחלקת בקרה״)."},
{c:"היסטוריה",q:"מה היה ״אביב העמים״ הערבי, ומה יצא ממנו?",h:"2011 — ירקן תוניסאי אחד.",a:"גל מחאות שהחל בתוניסיה (דצמבר 2010) והפיל שליטים בתוניסיה, מצרים (מובארכ), לוב (קדאפי) ותימן. בסוריה — מלחמת אזרחים (אסד נפל רק בדצמבר 2024); בלוב ותימן — כאוס ומלחמות. רק תוניסיה הפכה לזמן־מה לדמוקרטיה — וגם היא נסוגה.",m:"במצרים: שנה של שלטון האחים המוסלמים (מורסי), ואז הפיכה צבאית (א־סיסי, 2013).",d:"למה זה עיצב את המזרח התיכון של היום: הוואקום בסוריה הביא את דאעש (2014), את איראן וחיזבאללה לגבול ישראל, ואת רוסיה לים התיכון. מיליוני פליטים לאירופה שינו את הפוליטיקה שלה. ומדינות המפרץ הסיקו שיציבות עדיפה על דמוקרטיה — ומשם הדרך להסכמי אברהם. הלקח שהיסטוריונים מציינים: הפלת שליט קלה; בניית מוסדות במקומו — עניין של עשורים."},
// גאוגרפיה
{c:"גאוגרפיה",q:"מהם המצרים הימיים החשובים בעולם, ולמה הם ״נקודות חנק״?",h:"הורמוז, מאלאקה, באב אל־מנדב, סואץ, פנמה.",a:"מעברים צרים שסחר עולמי חייב לעבור בהם: הורמוז — 20% מהנפט בעולם; מאלאקה (בין מלזיה לאינדונזיה) — סחר סין–הודו–מפרץ; באב אל־מנדב — הכניסה לים סוף ולסואץ; תעלת סואץ — 12% מסחר העולם; תעלת פנמה — אטלנטי–שקט; הבוספורוס — הים השחור.",m:"סגירת הורמוז היא האיום האיראני האולטימטיבי; החות׳ים בבאב אל־מנדב הראו ב־2023–24 מה סגירה חלקית עושה.",d:"למה אילת קיימת ולמה מבצעים ימיים בים סוף: ישראל היא המדינה היחידה עם נמלים בשני ימים — ים תיכון וים סוף — ומעקף לסואץ (הרעיון ההיסטורי של קו נפט אילת–אשקלון, וה״מסדרון״ הודו–המפרץ–ישראל–אירופה, IMEC, מ־2023). מי ששולט בנקודות החנק שולט במחיר של הכל — ולכן צי אמריקאי יושב בבחריין."},
{c:"גאוגרפיה",q:"אילו מדינות גובלות בישראל, ומה אורך כל גבול בערך?",h:"ארבע מדינות ורצועה.",a:"מצרים (~208 ק״מ, סיני), ירדן (~300 ק״מ הכולל ים המלח והערבה — הארוך ביותר), סוריה (~76 ק״מ, רמת הגולן), לבנון (~80 ק״מ). ועוד: רצועת עזה (~51 ק״מ) והגדה המערבית (״הקו הירוק״ ~300 ק״מ).",m:"עם מצרים וירדן — שלום; עם סוריה ולבנון — הסכמי הפסקת אש בלבד (1949/1974), ללא גבול מוסכם.",d:"מה שרוב האנשים לא יודעים: הגבול עם ירדן הוא הגבול הארוך והשקט ביותר, ומוגן במידה רבה על ידי ממלכת ירדן עצמה — לכן יציבות ירדן היא אינטרס ביטחוני ישראלי ראשון במעלה. ״הקו הכחול״ עם לבנון סומן על ידי האו״ם ב־2000 (13 נקודות במחלוקת), וב־2022 סוכם גבול ימי עם לבנון — הסכם ראשון בין המדינות, בגלל גז."},
{c:"גאוגרפיה",q:"מהם חמשת האוקיינוסים, ואיזה מהם הגדול והעמוק?",h:"השקט הוא חצי מהמים בעולם.",a:"השקט (הגדול והעמוק — שקע מריאנה, ~11 ק״מ), האטלנטי, ההודי, הדרומי (סביב אנטארקטיקה, הוכר ב־2000), והארקטי (הקטן והרדוד).",m:"האוקיינוס השקט לבדו גדול מכל היבשות יחד.",d:"למה ״הדרומי״ ומה הזרם החזק בעולם: הזרם הצירקומפולרי סביב אנטארקטיקה מעביר פי 100 יותר מים מכל הנהרות בעולם יחד ומבודד את אנטארקטיקה — לכן היא הקפואה ביותר. שיא הגלים בעולם: 40°–50° דרום, ״הארבעים השואגים״ — אין יבשה שעוצרת את הרוח. וישראל? רק ים תיכון (חלק מהאטלנטי) וים סוף (חלק מההודי)."},
{c:"גאוגרפיה",q:"מהי ״טורקיה״ מבחינה גאוגרפית — למה היא ״גשר״ ולמה זה מקור כוחה?",h:"שתי יבשות, שני מצרים.",a:"97% אנטוליה (אסיה), 3% תראקיה (אירופה), והבוספורוס והדרדנלים — הכניסה היחידה לים השחור. גובלת ב־8 מדינות (יוון, בולגריה, גאורגיה, ארמניה, אזרבייג׳ן, איראן, עיראק, סוריה) ומהווה ציר לגז ונפט מהמזרח לאירופה.",m:"אמנת מונטרה (1936) נותנת לטורקיה שליטה על מעבר ספינות מלחמה למים השחור — כלי כוח אמיתי במלחמת אוקראינה.",d:"למה ארדואן יכול ״להתחצף״ לכולם: חברה בנאט״ו (הצבא השני בגודלו בברית) שקונה נשק מרוסיה, שולטת בגבול הפליטים לאירופה, וסוגרת/פותחת מצרים. גם קטר בגז, וגם היא: מיקום = כוח. ולישראל: ״שותפה־יריבה״ — סחר ענק בשני הכיוונים, ומתיחות פוליטית חריפה."},
{c:"גאוגרפיה",q:"מהם ״קווי הרוחב והאורך״, ומה ההבדל בין קו המשווה לגריניץ׳?",h:"אחד נתון על ידי הטבע, השני נבחר.",a:"קווי רוחב (מקבילים) מודדים צפון–דרום מ־0° בקו המשווה ל־90° בקטבים — טבעיים, נקבעים מסיבוב כדור הארץ. קווי אורך (מרידיאנים) מודדים מזרח–מערב מקו 0° — שרירותי, נקבע ב־1884 בגריניץ׳ (לונדון). ישראל: ~32° צפון, ~35° מזרח.",m:"כל 15° אורך = שעה של הפרש זמן; לכן ישראל UTC+2 (35/15 ≈ 2.3).",d:"טריק שימושי: קו רוחב אפשר למצוא בלי מכשירים — גובה כוכב הצפון מעל האופק = קו הרוחב שלך (בצפון); קו אורך דורש שעון מדויק, ולכן ״בעיית קו האורך״ הייתה הבעיה המדעית הגדולה של המאה ה־18 עד שג׳ון הריסון בנה כרונומטר ימי. GPS פותר את שתיהן ב־4 לוויינים — 3 למיקום, אחד לשעון."},
];
